INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("新年を迎え、新たに始まる一日を\nおみくじで占ってみませんか？\n良い運勢であるほど、\n沢山のプレゼントが貰えますよ♪", 1, 0, "", 190804, 1, 1, "カリン", 1, 0, 60000, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は姫吉！　あらゆる運気が最大を示しています！　　　今なら「伝説の吸血鬼」をも従え、世界征服も夢じゃありません！", 2, 0, "", 0, 0, 2, "", 1, 1, 60000, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は姫吉！　やること全てが最高潮！　やばいですね☆　ラッキーアイテムはおにぎり！　お腹一杯で幸せが続くでしょう！", 2, 0, "", 0, 0, 3, "", 1, 1, 60000, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は姫吉！　その高い運気はまさにショーグンの如く！　その溢れる威光は人々を惹きつけ、皆の人気者間違いなしです！", 2, 0, "", 0, 0, 4, "", 2, 1, 60000, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は大吉！　運気がどんどん高まっています！　　　　　何をやっても、最大効率で素晴らしい結果になりますよ♪", 2, 0, "", 0, 0, 5, "", 1, 2, 60000, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は大吉！　なにをやっても上手くいって大活躍！　　　そんな素敵なあなたを見て、後ろから誰かが……クスクス♪", 2, 0, "", 0, 0, 6, "", 1, 2, 60000, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は大吉！　運気が高く、何かに挑戦すると良い結果に！隠れた才能が引き出されそう！　目指せヒデサ……ではなく秀才！", 2, 0, "", 0, 0, 7, "", 2, 2, 60000, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は中吉！　商売運が上がってきています！　　　　　　ラッキーアイテムはたいやき！　和菓子パワーで売上アップです！", 2, 0, "", 0, 0, 8, "", 1, 3, 60000, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は中吉！　旅行運がぐんぐんと上昇中♪　　　　　　　もしかしたら、あの「マホマホ王国」にだって行けるかも♪", 2, 0, "", 0, 0, 9, "", 1, 3, 60000, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は中吉！　仕事運が急上昇中です！　　　　　　　　　きっと「煉獄に舞う一陣の疾風」の如き活躍ができますよ！", 2, 0, "", 0, 0, 10, "", 1, 3, 60000, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は中吉！　チャンスを待つと良い結果に！　　　　　　ラッキーアイテムのプリンを食べて、運を呼び込みましょう！", 2, 0, "", 0, 0, 11, "", 1, 3, 60000, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は中吉！　運気が着々と上昇中！　　　　　　　　　　精霊の加護を受けたかの如く、色々な事がうまくいきますよ♪", 2, 0, "", 0, 0, 12, "", 2, 3, 60000, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は小吉！　早朝に幸運の兆しあり！　　　　　　　　　もしかしたら、優しいお姉ちゃんが起こしにきてくれますよ♪", 2, 0, "", 0, 0, 13, "", 1, 4, 60000, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は小吉！　運気上昇中ですが、上がるまでが要注意！　ラッキーアニマルは熊！　本当の家族のように守ってくれるかも♪", 2, 0, "", 0, 0, 14, "", 1, 4, 60000, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は小吉！　外に出てゆっくり過ごすと運気が上昇！　　ラッキースポットは牧場。面白い出会いがありそうです♪", 2, 0, "", 0, 0, 15, "", 1, 4, 60000, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は小吉！　運気は高いけども、ハプニングには注意！　出かけた先で、「ふしんしゃ」扱いされてしまうかも……", 2, 0, "", 0, 0, 16, "", 1, 4, 60000, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は小吉！　根を詰めずにリラックスすると運気向上！　ラッキーパーソンはアイドル。歌があなたを幸せにしてくれます♪", 2, 0, "", 0, 0, 17, "", 2, 4, 60000, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("おみくじの結果はどうでしたか？\n新たに始まる一日が、あなたに\nとって良い日になりますように\nまた明日も遊びに来て下さいね♪", 3, 0, "", 190804, 2, 18, "カリン", 0, 0, 60000, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("おみくじは楽しんで頂けましたか？\nあなたの新たなる年が\n素晴らしいものになるよう、\n心からお祈りいたします", 3, 0, "", 190804, 3, 19, "カリン", 0, 0, 60000, 7);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("キミと出会ってもう\n1年もたつんだね！\nう～ん、いつも\n寝てばっかりだから、", 0, 0, "", 101201, 1, 20, "ハツネ", 0, 0, 80001, 1);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("少しでも\n寝る時間を減らして\nキミと一緒にいる\n時間増やしたいなぁ♪", 0, 0, "", 101201, 2, 21, "ハツネ", 0, 0, 80001, 1);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("あなたと知り合ってから\nもう1年…\n時がたつのは\n早いですね", 1, 0, "", 103801, 1, 22, "シオリ", 0, 0, 80001, 1);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("来年も、\n一緒にいられたら…\nうれしいな", 1, 0, "", 103801, 2, 23, "シオリ", 0, 0, 80001, 1);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("あなたと一緒にいるようになって、\nもう1年ですか…", 0, 0, "", 103601, 1, 24, "キョウカ", 0, 0, 80001, 2);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("最初の頃よりも、頼もしく\nなりましたね。私はどうですか？\n成長していますか？", 0, 0, "", 103601, 2, 25, "キョウカ", 0, 0, 80001, 2);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("おにいちゃんとあってから、\n1年たったよ～！", 1, 0, "", 102001, 1, 26, "ミミ", 0, 0, 80001, 2);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ミミね、おにいちゃんと\nいっぱい遊べてたのしかったな～♪\nこれからもずっと\nいっしょにいてね～！", 1, 0, "", 102001, 2, 27, "ミミ", 0, 0, 80001, 2);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("にいちゃんがミソギのイタズラに\n引っかかり続けてもう1年かぁ", 2, 0, "", 100401, 1, 28, "ミソギ", 0, 0, 80001, 2);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("…これからもいっぱいミソギと\n遊んでね、にいちゃん！", 2, 0, "", 100401, 2, 29, "ミソギ", 0, 0, 80001, 2);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("もう王子はんと会うてから\n1年ぐらいたつそうどすえ\n早いもんやなあ", 0, 0, "", 101001, 1, 30, "マホ", 0, 0, 80001, 3);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("このままやと、\nうちもあっという間に\n干からびてしまいそうどすえ\nなーんてな。うふふ", 0, 0, "", 101001, 2, 31, "マホ", 0, 0, 80001, 3);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("お主と会って早1年じゃな\nこれからも存分に尽くすがよい", 1, 0, "", 104401, 1, 32, "イリヤ", 0, 0, 80001, 3);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("わらわもたまには、お主の献身に\n報いてやらぬでもない♪", 1, 0, "", 104401, 2, 33, "イリヤ", 0, 0, 80001, 3);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("もう、キミと出会って結構な時間が\nたつさ～。でも、私たちの旅は\nまだまだ始まったばかりさ～！", 2, 0, "", 101701, 1, 34, "カオリ", 0, 0, 80001, 3);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("これからも、どうぞよろしく\nお願いするさ～！", 2, 0, "", 101701, 2, 35, "カオリ", 0, 0, 80001, 3);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("あんたと出会ってからもうそんなに\nたつのね～", 0, 0, "", 102801, 1, 36, "サレン", 0, 0, 80001, 4);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("あっという間だったって感じるほど\n楽しかったわ！\nこれからも一緒に頑張りましょ！", 0, 0, "", 102801, 2, 37, "サレン", 0, 0, 80001, 4);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("出会ってから1年間、ずっと\nご迷惑をかけっぱなしで、\nすみません…", 1, 0, "", 102501, 1, 38, "スズメ", 0, 0, 80001, 4);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("これからはもっと頑張りますから\n見ていてくださいね\nできれば…\n今までよりも、私の近くで♪", 1, 0, "", 102501, 2, 39, "スズメ", 0, 0, 80001, 4);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("振り返れば、今までいろんなことが\nあったにゃあ…", 0, 0, "", 104601, 1, 40, "タマキ", 0, 0, 80001, 5);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("これからも、二人でたくさんの\n思い出をがっぽり作っていく\nにゃー！", 0, 0, "", 104601, 2, 41, "タマキ", 0, 0, 80001, 5);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("キミとの師弟関係も、\nもう1年なのね…\nでもキミに教えることは、", 1, 0, "", 104801, 1, 42, "ミフユ", 0, 0, 80001, 5);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("まだまだいっぱいあるわ\nこれからも、\nしっかりついて来てね！", 1, 0, "", 104801, 2, 43, "ミフユ", 0, 0, 80001, 5);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("あなたさまと出会ってもう1年…", 0, 0, "", 103201, 1, 44, "アキノ", 0, 0, 80001, 6);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("光陰矢のごとし、とはまさに\nこのことですわ。…思い出は決して\nお金では買えませんわね", 0, 0, "", 103201, 2, 45, "アキノ", 0, 0, 80001, 6);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ダメな私を1年間も見捨てないで\nくれて、本当にありがとう", 1, 0, "", 103401, 1, 46, "ユカリ", 0, 0, 80001, 6);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("情けないところいっぱいみせるかも\nしれないけど、これからも一緒に\nいてくれると、うれしいな", 1, 0, "", 103401, 2, 47, "ユカリ", 0, 0, 80001, 6);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("オマエと出会ってもう1年か\nまさかこのワタシの結婚相手に\nなろうとはな…", 0, 0, "", 107101, 1, 48, "クリスティーナ", 0, 0, 80001, 7);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ともかくこれからも\n愉しませてくれよ☆", 0, 0, "", 107101, 2, 49, "クリスティーナ", 0, 0, 80001, 7);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("君と出会ってからもう1年か。\n以前と比べて私の表情もいくらか\n柔らかくなった気がするんだが、\nどうだろう？", 1, 0, "", 104701, 1, 50, "ジュン", 0, 0, 80001, 7);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("見えないから分からないって？\nそれもそうだな…", 1, 0, "", 104701, 2, 51, "ジュン", 0, 0, 80001, 7);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("もう1年たったみたいだね\nあなたをからかってばかりだった\nけど、楽しかった♪", 0, 0, "", 103701, 1, 52, "トモ", 0, 0, 80001, 8);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("これからもよろしくね！", 0, 0, "", 103701, 2, 53, "トモ", 0, 0, 80001, 8);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("出会って、もう1年たっちゃった\nんスね。なんだか意外ッス", 1, 0, "", 100501, 1, 54, "マツリ", 0, 0, 80001, 8);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("毎日楽しくて、あっという間に過ぎ\nちゃったみたいなんスよね\nこれからも一緒に悪と戦うッス！", 1, 0, "", 100501, 2, 55, "マツリ", 0, 0, 80001, 8);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("オマエと会って1年なの！\n全然成仏もできなかったし、", 0, 0, "", 100701, 1, 56, "ミヤコ", 0, 0, 80001, 9);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("生き返りもしなかったけど、\nすごく楽しかったの～♪\nオマエとプリンがあれば、\nミヤコはハッピーなの～♪", 0, 0, "", 100701, 2, 57, "ミヤコ", 0, 0, 80001, 9);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("あなたと出会って1年なんですね\nでも、私の占いでは、私とあなたは", 1, 0, "", 103101, 1, 58, "シノブ", 0, 0, 80001, 9);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("来年も再来年も一緒にいるようです\nふふ、よろしくお願いしますね", 1, 0, "", 103101, 2, 59, "シノブ", 0, 0, 80001, 9);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("貴様が閃光のシグルドとして覚醒し\nもう1年か…。これからも我らの\n長き戦いに終わりはないが、", 0, 0, "", 100901, 1, 60, "アンナ", 0, 0, 80001, 10);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("それでも貴様となら…\n添い遂げる覚悟はできているぞ！", 0, 0, "", 100901, 2, 61, "アンナ", 0, 0, 80001, 10);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("君と出会ってもう1年だって！\n早いねー！", 1, 0, "", 101301, 1, 62, "ナナカ", 0, 0, 80001, 10);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("これからも最強のバディタッグで\n大活躍だー！\n頼りにしてるよ、相棒！", 1, 0, "", 101301, 2, 63, "ナナカ", 0, 0, 80001, 10);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("1年たつのって、あっという間ね\nまだまだ君の知らない部分が\nたくさんあるし…", 0, 0, "", 105101, 1, 64, "ミツキ", 0, 0, 80001, 11);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("これからも、いろんなところを\n調べさせてね？", 0, 0, "", 105101, 2, 65, "ミツキ", 0, 0, 80001, 11);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("お前さんと出会ってもう1年か\n助太刀するつもりが", 1, 0, "", 105601, 1, 66, "ルカ", 0, 0, 80001, 11);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("逆に助けられたりもしたね\nこれからもよろしく頼むよ！", 1, 0, "", 105601, 2, 67, "ルカ", 0, 0, 80001, 11);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("早いものですわね、あなた様と\nお会いして、もう1年…", 2, 0, "", 102701, 1, 68, "エリコ", 0, 0, 80001, 11);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("あなた様といると、時があっと\nいう間に過ぎてしまいます\n時間を止める研究をしなくては\nいけませんね…", 2, 0, "", 102701, 2, 69, "エリコ", 0, 0, 80001, 11);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("お兄ちゃんと会ってから、もう、\n1年なんだね。私、少しは\nお姉ちゃんっぽくなったかな？", 0, 0, "", 102301, 1, 70, "アヤネ", 0, 0, 80001, 12);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("あ、ぷうきちもお兄ちゃんっぽく\nなったよね？", 0, 0, "", 102301, 2, 71, "アヤネ", 0, 0, 80001, 12);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("あなたと出会って、\nもう1年がたったんですね…\nこれからもそばにいて、", 1, 0, "", 104201, 1, 72, "チカ", 0, 0, 80001, 12);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("私のことを見守ってください\nできることなら、ずっと…", 1, 0, "", 104201, 2, 73, "チカ", 0, 0, 80001, 12);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("お兄ちゃんと出会って1年かぁ\n私、相変わらずダメダメで…", 2, 0, "", 102101, 1, 74, "クルミ", 0, 0, 80001, 12);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("で、でもこれからもずっと…\n一緒にいたいなぁ…", 2, 0, "", 102101, 2, 75, "クルミ", 0, 0, 80001, 12);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("再会してちょうど1年だね\nお祝いにごちそう作ってきたよ～♪\n特製ケーキと、お寿司と、", 0, 0, "", 104901, 1, 76, "シズル", 0, 0, 80001, 13);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ハンバーグと、カレーと、\nシチューと、あ、隠しきれない隠し\n味は、お姉ちゃんの愛情だよ！", 0, 0, "", 104901, 2, 77, "シズル", 0, 0, 80001, 13);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("お兄ちゃんと再会して、もう1年\nなんですね。\n会えなかった時を思うと、", 1, 0, "", 101101, 1, 78, "リノ", 0, 0, 80001, 13);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("信じられないくらい幸せな1年\nでした！もう絶対、私から離れ\nないでくださいね♪", 1, 0, "", 101101, 2, 79, "リノ", 0, 0, 80001, 13);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("騎士クンと出会ってから今まで、\nいろんなことがあったよね\n楽しいこと、ドキドキしたこと…", 0, 0, "", 100201, 1, 80, "ユイ", 0, 0, 80001, 14);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("そんな日々をこれからも、\nず、ずっと一緒に…\n過ごしていきたいな…！", 0, 0, "", 100201, 2, 81, "ユイ", 0, 0, 80001, 14);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("騎士くんと出会って、まだ1年しか\nたってないんだ！？", 1, 0, "", 100101, 1, 82, "ヒヨリ", 0, 0, 80001, 14);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("なんかもうずっと一緒にいる気が\nするなぁ…えへへ。これからの\n1年もまたよろしくねっ！\n騎士くん！", 1, 0, "", 100101, 2, 83, "ヒヨリ", 0, 0, 80001, 14);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("初めてキミに出会って1年…\n随分見違えたね私もキミも、\n更に強くなっていく…", 2, 0, "", 100301, 1, 84, "レイ", 0, 0, 80001, 14);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("キミに背中を預けられる日が、\n早くきますように", 2, 0, "", 100301, 2, 85, "レイ", 0, 0, 80001, 14);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("1年もわたしのことを、忘れない\nでいてくれて、ありがとうござい\nます！", 0, 0, "", 105801, 1, 86, "ペコリーヌ", 0, 0, 80001, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("これからもずっと、覚えていて\nくださいね！", 0, 0, "", 105801, 2, 87, "ペコリーヌ", 0, 0, 80001, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("こうして1年も、主さまのおそばに\n置いていただけて、とても光栄\nです。どうかこれからも、", 1, 0, "", 105901, 1, 88, "コッコロ", 0, 0, 80001, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("末永く主さまをお世話させて\nください。わたくしは、ずっと\n主さまのガイド役でいたいのです", 1, 0, "", 105901, 2, 89, "コッコロ", 0, 0, 80001, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("1年か、まっさかこんなに長い\n付き合いになるなんてね～\nでも…わりと楽しい1年だったかも", 2, 0, "", 106001, 1, 90, "キャル", 0, 0, 80001, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("だから、もうしばらくあんたに\n付き合ってやるわよ喜びなさい！", 2, 0, "", 106001, 2, 91, "キャル", 0, 0, 80001, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("新しい年のはじめに、\nおみくじはいかがでしょうか？\nよい運勢であるほど、\n沢山プレゼントが貰えますよ♪", 1, 0, "", 112101, 1, 92, "スズメ", 1, 0, 60001, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は姫吉！　あらゆる運気が最大を示しています！　　　今なら「伝説の吸血鬼」をも従え、世界征服も夢じゃありません！", 2, 0, "", 0, 0, 93, "", 1, 1, 60001, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は姫吉！　やること全てが最高潮！　やばいですね☆　ラッキーアイテムはおにぎり！　お腹一杯で幸せが続くでしょう！", 2, 0, "", 0, 0, 94, "", 1, 1, 60001, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は姫吉！　最強の運勢でどんなドジも跳ね除けます！　大切な人と一緒に、最高の一日になること間違いなし！", 2, 0, "", 0, 0, 95, "", 1, 1, 60001, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は姫吉！　どんな挑戦も上手くいく、最高の運勢です！理想の自分に変身できる絶好の機会！　新しい一歩を踏み出そう！", 2, 0, "", 0, 0, 96, "", 1, 1, 60001, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は姫吉！　その高い運気はまさにショーグンの如く！　その溢れる威光は人々を惹きつけ、皆の人気者間違いなしです！", 2, 0, "", 0, 0, 97, "", 2, 1, 60001, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は大吉！　運気がどんどん高まっています！　　　　　何をやっても、最大効率で素晴らしい結果になりますよ♪", 2, 0, "", 0, 0, 98, "", 1, 2, 60001, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は大吉！　なにをやっても上手くいって大活躍！　　　そんな素敵なあなたを見て、後ろから誰かが……クスクス♪", 2, 0, "", 0, 0, 99, "", 1, 2, 60001, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は大吉！　ラッキーワードは「ちぇる～ん♪」　　　　出会う人みんなに言ってあげると、ハッピーになれますよ！", 2, 0, "", 0, 0, 100, "", 1, 2, 60001, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は大吉！　運勢はバッチリで無敵状態！　　　　　　　龍眼で全てを見通して、思い通りの一日を過ごしましょう！", 2, 0, "", 0, 0, 101, "", 1, 2, 60001, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は大吉！　運気が高く、何かに挑戦すると良い結果に！隠れた才能が引き出されそう！　目指せヒデサ……ではなく秀才！", 2, 0, "", 0, 0, 102, "", 2, 2, 60001, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は中吉！　商売運が上がってきています！　　　　　　ラッキーアイテムはたいやき！　和菓子パワーで売上アップです！", 2, 0, "", 0, 0, 103, "", 1, 3, 60001, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は中吉！　旅行運がぐんぐんと上昇中♪　　　　　　　もしかしたら、あの「マホマホ王国」にだって行けるかも♪", 2, 0, "", 0, 0, 104, "", 1, 3, 60001, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は中吉！　仕事運が急上昇中です！　　　　　　　　　きっと「煉獄に舞う一陣の疾風」の如き活躍ができますよ！", 2, 0, "", 0, 0, 105, "", 1, 3, 60001, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は中吉！　チャンスを待つと良い結果に！　　　　　　ラッキーアイテムのプリンを食べて、運を呼び込みましょう！", 2, 0, "", 0, 0, 106, "", 1, 3, 60001, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は中吉！　お出かけした先で良縁に恵まれそうです！　ダウナー系あざとい女子が、あま～い飴をくれるかも？", 2, 0, "", 0, 0, 107, "", 1, 3, 60001, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は中吉！　大抵のことはゴリ押しでなんとかできます！ラッキープレイスはゲーセン。パンチングマシンでストレス発散！", 2, 0, "", 0, 0, 108, "", 1, 3, 60001, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は中吉！　運気が着々と上昇中！　　　　　　　　　　精霊の加護を受けたかの如く、色々な事がうまくいきますよ♪", 2, 0, "", 0, 0, 109, "", 2, 3, 60001, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は小吉！　早朝に幸運の兆しあり！　　　　　　　　　もしかしたら、優しいお姉ちゃんが起こしにきてくれますよ♪", 2, 0, "", 0, 0, 110, "", 1, 4, 60001, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は小吉！　運気上昇中ですが、上がるまでが要注意！　ラッキーアニマルは熊！　本当の家族のように守ってくれるかも♪", 2, 0, "", 0, 0, 111, "", 1, 4, 60001, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は小吉！　外に出てゆっくり過ごすと運気が上昇！　　ラッキースポットは牧場。面白い出会いがありそうです♪", 2, 0, "", 0, 0, 112, "", 1, 4, 60001, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は小吉！　運気は高いけども、ハプニングには注意！　出かけた先で、「ふしんしゃ」扱いされてしまうかも……", 2, 0, "", 0, 0, 113, "", 1, 4, 60001, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は小吉！　同腹一心の友だちが見つかるかも！　　　　キーワードは「ユニちゃんズ」、記憶に刻みましょう！", 2, 0, "", 0, 0, 114, "", 1, 4, 60001, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は小吉！　思わぬ相手と仲良くなれるかも？　　　　　うっかり毒舌をもらしてしまわないように要注意です！", 2, 0, "", 0, 0, 115, "", 1, 4, 60001, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は小吉！　根を詰めずにリラックスすると運気向上！　ラッキーパーソンはアイドル。歌があなたを幸せにしてくれます♪", 2, 0, "", 0, 0, 116, "", 2, 4, 60001, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("おみくじの結果はいかがでしたか？\n新たに始まる一日が、\nあなたにとってよい日になりますように\n明日もお待ちしていますね♪", 3, 0, "", 112101, 2, 117, "スズメ", 0, 0, 60001, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("おみくじ、楽しんで頂けましたか？\nあなたの新しい年が\n素晴らしいものになるよう、\n心からお祈りしますね", 3, 0, "", 112101, 3, 118, "スズメ", 0, 0, 60001, 7);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ヒューヒュー♪\nドンドンパフパフー♪", 0, 0, "", 105801, 1, 119, "ペコリーヌ", 0, 0, 80003, 1);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ひゅーひゅー\nどんどんぱふぱふー\nでございます", 1, 0, "", 105901, 1, 120, "コッコロ", 0, 0, 80003, 1);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("さぁ、キャルさまもご一緒に\nどんどんぱふぱふいたしましょう", 1, 0, "", 105901, 2, 121, "コッコロ", 0, 0, 80003, 1);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("え？　ちょっと\nいきなりなにっ？", 2, 0, "", 106001, 1, 122, "キャル", 0, 0, 80003, 1);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ドンドンパフパフってなんなの？\nあたしにも分かるように\nちゃんと説明しなさいっての！", 2, 0, "", 106001, 2, 123, "キャル", 0, 0, 80003, 1);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("実はですねキャルちゃん！\nもうすぐわたしたちにとっての\n大切な節目──", 0, 0, "", 105801, 2, 124, "ペコリーヌ", 0, 0, 80003, 1);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("『プリンセスコネクト！\nRe:Dive』\n2.5周年なんですよ！\nやばいですね☆", 0, 0, "", 105801, 3, 125, "ペコリーヌ", 0, 0, 80003, 1);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ですからその日に向けて\n今から気分を盛り上げているのです", 1, 0, "", 105901, 3, 126, "コッコロ", 0, 0, 80003, 1);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ああ、そういえば\nそんな時期だっけ\nって言っても、もう少し先じゃない\n気が早いんじゃないの？", 2, 0, "", 106001, 3, 127, "キャル", 0, 0, 80003, 1);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("いいえ、キャルさま\nこういったお祝いは準備から\n楽しむものでございます\nそうですよね、ペコリーヌさま", 1, 0, "", 105901, 4, 128, "コッコロ", 0, 0, 80003, 1);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("その通りです♪　というわけで！\nカウントダウンの始まりですよ！\nみんなで一緒に2.5周年に向けて\n盛り上がっていきましょー☆", 0, 0, "", 105801, 4, 129, "ペコリーヌ", 0, 0, 80003, 1);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ド、ドンドンパフパフ～\nって何言わせんのよ！\nまったくもう、浮かれちゃってさ", 2, 0, "", 106001, 4, 130, "キャル", 0, 0, 80003, 1);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ふふ。キャルさまもワクワクして\nおいでのようですね\nそれでは主さま。大切な記念日まで\nどうぞご期待くださいませ", 1, 0, "", 105901, 5, 131, "コッコロ", 0, 0, 80003, 1);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("記念日を盛り上げるったって\n一体どうしたらいいのよ？\nあたし、そういうの\n苦手なんだけど…", 0, 0, "", 106001, 5, 132, "キャル", 0, 0, 80003, 2);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("あら、キャルさん\nどうかなさいましたか？\n何かお困りのようですけど", 1, 0, "", 190801, 1, 133, "カリン", 0, 0, 80003, 2);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("げっ…カリンじゃない\nなんでもないわよ！", 0, 0, "", 106001, 6, 134, "キャル", 0, 0, 80003, 2);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("そうなのですか？\nキャルさんのことですからてっきり\n2.5周年をどう盛り上げたら\nいいか悩んでいるのかと…", 1, 0, "", 190801, 2, 135, "カリン", 0, 0, 80003, 2);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("分かってんじゃないのよ！？\nいっ、いや、違うけどね！\nあたしは別にそんなことで\n悩んでないわよっ？", 0, 0, "", 106001, 7, 136, "キャル", 0, 0, 80003, 2);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ふふっ…\nこういう時は、真心を込めて\n気持ちをそのまま口にしたら\nいいのではないでしょうか？", 1, 0, "", 190801, 3, 137, "カリン", 0, 0, 80003, 2);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("気持ちを、ねぇ\nそれが一番難しいんじゃない…\nそもそも、あたしは記念日とか\n別にどうだっていいし", 0, 0, "", 106001, 8, 138, "キャル", 0, 0, 80003, 2);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("…まあ、ペコリーヌもコロ助も\nやけに楽しそうだったから…\nこういうお祭り騒ぎみたいなのも\nたまにはいいかな、とは思うけど", 0, 0, "", 106001, 9, 139, "キャル", 0, 0, 80003, 2);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("なるほどなるほど～\nキャルさんは【美食殿】で祝う\n2.5周年を心から楽しみに\nしている、ということですね！", 1, 0, "", 190801, 4, 140, "カリン", 0, 0, 80003, 2);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("はぁ！？\nどこ聞いたらそうなるのよ！\nあたしは別に楽しみになんか…！", 0, 0, "", 106001, 10, 141, "キャル", 0, 0, 80003, 2);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("キャルさんの心からの想い\nみなさんにも伝わったでしょうか？\n私も2.5周年が楽しみです！\n以上、カリンがお伝えしました！", 1, 0, "", 190801, 5, 142, "カリン", 0, 0, 80003, 2);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("心からの想いって何なのよ！？\n勝手に人の言葉を\n捻じ曲げんじゃないわよ！\nこのくそ眼鏡ーーーっ！", 0, 0, "", 106001, 11, 143, "キャル", 0, 0, 80003, 2);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ペコリーヌさま、もうすぐ\n記念日でございますね\nこういった節目というのは\n感慨深いものでございます", 0, 0, "", 105901, 6, 144, "コッコロ", 0, 0, 80003, 3);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("色んな思い出が蘇ってきますね！\n楽しい出来事が\nいっぱいありました♪", 1, 0, "", 105801, 5, 145, "ペコリーヌ", 0, 0, 80003, 3);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("はい、そうでございますね\n主さまも【美食殿】の活動の他にも\nいろんなご経験をされたと\n聞いておりますよ", 0, 0, "", 105901, 7, 146, "コッコロ", 0, 0, 80003, 3);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("たしか…ランドソルで話題沸騰と\nなっていた、魔法少女なるものに\nお会いになられたとか", 0, 0, "", 105901, 8, 147, "コッコロ", 0, 0, 80003, 3);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("魔法少女って、あの美味しくって\n栄養たっぷりの大ヒット商品\n『魔法少女ソーセージ』の箱に\n描いてある女の子のことですか！？", 1, 0, "", 105801, 6, 148, "ペコリーヌ", 0, 0, 80003, 3);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("あのソーセージ\n美味しいんですよね～♪\nわたしもたっくさん食べてますよ！", 1, 0, "", 105801, 7, 149, "ペコリーヌ", 0, 0, 80003, 3);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("あとは、牧場に素敵な温泉が\n出来たとか…", 0, 0, "", 105901, 9, 150, "コッコロ", 0, 0, 80003, 3);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("牧場ですか！？　温泉につかって\nチーズもオツですね～♪　考えた\nだけでよだれが出ちゃいそうです！\nやばいですね☆", 1, 0, "", 105801, 8, 151, "ペコリーヌ", 0, 0, 80003, 3);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ペコリーヌさま\n言ってるそばからよだれが…\n今お拭きしますね。ふき、ふき", 0, 0, "", 105901, 10, 152, "コッコロ", 0, 0, 80003, 3);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("えへへ、ありがとうございます\nコッコロちゃん！", 1, 0, "", 105801, 9, 153, "ペコリーヌ", 0, 0, 80003, 3);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("それにしても、主さまは\n【美食殿】の一員として様々な\n美食と出会われていたのですね\nわたくし、感服いたしました", 0, 0, "", 105901, 11, 154, "コッコロ", 0, 0, 80003, 3);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("これからもたくさん冒険をして\nめいっぱい美食を\n味わい尽くしましょうね！", 1, 0, "", 105801, 10, 155, "ペコリーヌ", 0, 0, 80003, 3);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("2.5周年カウントダウン♪\nキャルちゃんキャルちゃん！\nわくわくしますね☆", 0, 0, "", 105801, 11, 156, "ペコリーヌ", 0, 0, 80003, 4);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("あぁもう、うるさいわね～\nまだまだ先でしょ？\nちょっとは落ち着きなさいよ", 1, 0, "", 106001, 12, 157, "キャル", 0, 0, 80003, 4);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("キャルちゃんだって最近\nソワソワしてるじゃないですか～\nさっきもご機嫌そうに鼻歌とか\n歌ってましたよね？", 0, 0, "", 105801, 12, 158, "ペコリーヌ", 0, 0, 80003, 4);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("なっ…！　き、聞いてたの！？\nじゃない、歌ってないわよ！？\nあんたいい加減なこと言うと\nぶっ殺すわよ！？", 1, 0, "", 106001, 13, 159, "キャル", 0, 0, 80003, 4);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("えっへへ～♪\nわたしは最近のキャルちゃんが\nもっともっと大好きですよ♪\nすごく積極的になりましたよね！", 0, 0, "", 105801, 13, 160, "ペコリーヌ", 0, 0, 80003, 4);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("…積極的？\nなんの話よ？", 1, 0, "", 106001, 14, 161, "キャル", 0, 0, 80003, 4);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("またまた～♪\nアイドルを目指そうとしたこと\n忘れちゃったんですか？", 0, 0, "", 105801, 14, 162, "ペコリーヌ", 0, 0, 80003, 4);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ムーサの町で\nきゃるきゃる～ん☆　って！", 0, 0, "", 105801, 15, 163, "ペコリーヌ", 0, 0, 80003, 4);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("あっ…！？　ちちち違うわよっ！\nあれは操られてただけで\nあたしはアイドルなんか\n目指してないっての！！", 1, 0, "", 106001, 15, 164, "キャル", 0, 0, 80003, 4);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("本当に本当ですか？\nわたし、キャルちゃんとっても\n乗り気だなって\n思ってたんですけど～", 0, 0, "", 105801, 16, 165, "ペコリーヌ", 0, 0, 80003, 4);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("まぁ、悪くはなかったけど…って\nだ、だから目指してないって\n言ってるでしょ！！\nなんてこと思い出させんのよ！？", 1, 0, "", 106001, 16, 166, "キャル", 0, 0, 80003, 4);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ああ…ダメだわ…\nもう殺すしかない…\n2.5周年が来る前に\n記憶ごと消し去ってやるー！", 1, 0, "", 106001, 17, 167, "キャル", 0, 0, 80003, 4);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("2.5周年まであと10日…\nふ～ん？\n案外早いもんね？", 0, 0, "", 106001, 18, 168, "キャル", 0, 0, 80003, 5);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("そうでございますね…\nその日のためにやるべきことは\nまだまだございます\n気を引き締めねばなりません…！", 1, 0, "", 105901, 12, 169, "コッコロ", 0, 0, 80003, 5);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("やる気十分ねコロ助…\nそんな気負ってるとしんどいわよ？\nお気楽にやりましょ？", 0, 0, "", 106001, 19, 170, "キャル", 0, 0, 80003, 5);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("キャルさま…\nありがとうございます\nキャルさまは本当に\n優しいおかたです", 1, 0, "", 105901, 13, 171, "コッコロ", 0, 0, 80003, 5);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("な、なにわけの分かんないこと\n言ってんのよ…\nあたしは優しくなんかないっての", 0, 0, "", 106001, 20, 172, "キャル", 0, 0, 80003, 5);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("そんなことはございません\n…あの、実はわたくし\nキャルさまに\nひとつお願いがございまして", 1, 0, "", 105901, 14, 173, "コッコロ", 0, 0, 80003, 5);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("お願い？　珍しいわね\nコロ助がそんなこと言うなんて\n…まあ、あたしに出来ることなら\n別にいいけど", 0, 0, "", 106001, 21, 174, "キャル", 0, 0, 80003, 5);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ありがとうございます\n実は記念日へ向けて\n『かくし芸』というものを\n用意してみようかと思いまして", 1, 0, "", 105901, 15, 175, "コッコロ", 0, 0, 80003, 5);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("かくし芸？", 0, 0, "", 106001, 22, 176, "キャル", 0, 0, 80003, 5);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("はい。きゃるきゃる～ん☆　を\n参考に、ころころ～ん☆　という\nご挨拶を考えてみたのですが\nポーズがうまくいかなくて…", 1, 0, "", 105901, 16, 177, "コッコロ", 0, 0, 80003, 5);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("～～！！　ちょっと褒められて\nいい気になって損したわ！！\nふざけんなふざけんな\nふ～ざ～け～ん～な～っ！！", 0, 0, "", 106001, 23, 178, "キャル", 0, 0, 80003, 5);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("あと９日！　もうすぐですよ♪\nえへへ、楽しみで楽しみで\nごはんが進みますね☆", 0, 0, "", 105801, 17, 179, "ペコリーヌ", 0, 0, 80003, 6);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ごはんが進みますね☆\nじゃなーい！\nいくらなんでも食べ過ぎよ！\n記念日、迎えられなくなるわよ！？", 2, 0, "", 106001, 24, 180, "キャル", 0, 0, 80003, 6);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("大丈夫ですよキャルさま\n食事はわたくしたちの\n歩んできた道そのもの\nなのですから", 1, 0, "", 105901, 17, 181, "コッコロ", 0, 0, 80003, 6);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("さっすがコッコロちゃん\nいいことを言いますね！\nそう、わたしたち\n【美食殿】の活動目的は─", 0, 0, "", 105801, 18, 182, "ペコリーヌ", 0, 0, 80003, 6);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("─みんなで楽しく食事をすること\nでしょ？\nあれだけ食べ歩いてきたんだから\n分かってるわよ", 2, 0, "", 106001, 25, 183, "キャル", 0, 0, 80003, 6);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("はい…そうでございますね♪\nそれにしてもわたくしたち\n本当にいろいろなものを\n食べ歩いてきましたね…", 1, 0, "", 105901, 18, 184, "コッコロ", 0, 0, 80003, 6);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("そうね…ほんっとうにね…\n毒まみれのニセドラゴンとか\n恐竜…は逃げられちゃったっけ\nあとワニゴ…ワニの魔物とかね", 2, 0, "", 106001, 26, 185, "キャル", 0, 0, 80003, 6);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("そして、とうとう本物の\nドラゴンまで相手に\nしちゃったのよね、あたしたちって", 2, 0, "", 106001, 27, 186, "キャル", 0, 0, 80003, 6);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("信じられない強さだったわね\nあのドラゴン…やっぱり\n作戦はしっかり立てていかないと\nダメよね", 2, 0, "", 106001, 28, 187, "キャル", 0, 0, 80003, 6);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("えへへ…☆\nキャルちゃんが色んなことを\n覚えていてくれて\nうれしいです♪", 0, 0, "", 105801, 19, 188, "ペコリーヌ", 0, 0, 80003, 6);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("わたくしも鮮明に覚えておりますよ\n主さまもきっと…♪", 1, 0, "", 105901, 19, 189, "コッコロ", 0, 0, 80003, 6);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("あったり前でしょ！\n忘れないわよ、あんな滅茶苦茶な\nものばかり食べさせられて！\n…忘れられるわけ、ないじゃない", 2, 0, "", 106001, 29, 190, "キャル", 0, 0, 80003, 6);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ねえちょっと、ちょっと待って！？\nカリンから、2.5周年記念の\n生放送に出演してほしいって\n言われたんだけど！", 0, 0, "", 106001, 30, 191, "キャル", 0, 0, 80003, 7);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("なんでそういう大事なことを\n急に言うわけ！？\nそんなの聞いてないわよ～！？", 0, 0, "", 106001, 31, 192, "キャル", 0, 0, 80003, 7);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("いっぱい人に見られちゃうのよね？\nなんであたしがそんなこと…", 0, 0, "", 106001, 32, 193, "キャル", 0, 0, 80003, 7);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("あー\nあー\n…声、これで大丈夫かしら？", 0, 0, "", 106001, 33, 194, "キャル", 0, 0, 80003, 7);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("聞き取りにくいかもしれないわね…\nもうちょっと明るい方がいいかも\nえっと…こんな感じ？", 0, 0, "", 106001, 34, 195, "キャル", 0, 0, 80003, 7);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("オイッスー☆", 0, 0, "", 106001, 35, 196, "キャル", 0, 0, 80003, 7);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("……\nいや、ないわ\nいつもどおりが一番ね、うん", 0, 0, "", 106001, 36, 197, "キャル", 0, 0, 80003, 7);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("もう、記念の生放送なんて\n超責任重大なやつじゃない…\nもしなにか失敗とかしたら…", 0, 0, "", 106001, 37, 198, "キャル", 0, 0, 80003, 7);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ど、どど、どうしよう！？\n緊張してきちゃった…！！", 0, 0, "", 106001, 38, 199, "キャル", 0, 0, 80003, 7);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("主さま、わたくし\nペコリーヌさまとキャルさまと共に\n2.5周年を祝う生放送に\n出演する大役を仰せつかりました", 0, 0, "", 105901, 20, 200, "コッコロ", 0, 0, 80003, 8);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("多くの方々に\n『プリンセスコネクト！\nRe:Dive』の魅力をお伝えする\n重要な役割でございます", 0, 0, "", 105901, 21, 201, "コッコロ", 0, 0, 80003, 8);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("わたくし、全身全霊をもって\n生放送に取り組みたいと\n思っております", 0, 0, "", 105901, 22, 202, "コッコロ", 0, 0, 80003, 8);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ですが、もしかしたら\nセリフを噛んでしまったり\n段取りを間違えてしまったり\nするかもしれません…", 0, 0, "", 105901, 23, 203, "コッコロ", 0, 0, 80003, 8);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("そのようなことがないよう\n練習はしっかりしておかなくては\nまずはこちらから…", 0, 0, "", 105901, 24, 204, "コッコロ", 0, 0, 80003, 8);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("オイッスー☆", 0, 0, "", 105901, 25, 205, "コッコロ", 0, 0, 80003, 8);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("先ほどキャルさまが練習されて\nいるのをお見かけしたので\nわたくしもと思いまして…\nいかがでしょうか？", 0, 0, "", 105901, 26, 206, "コッコロ", 0, 0, 80003, 8);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("良い感じ、ですか？\n…ふふ、ありがとうございます\n主さまのあたたかいお言葉があれば\nわたくしは百人力でございます", 0, 0, "", 105901, 27, 207, "コッコロ", 0, 0, 80003, 8);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("この大役を無事に成し遂げ\n主さまに素敵な2.5周年を\n迎えていただけるよう…\nわたくし、尽力いたしますね", 0, 0, "", 105901, 28, 208, "コッコロ", 0, 0, 80003, 8);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("オイッスー☆", 0, 0, "", 105801, 20, 209, "ペコリーヌ", 0, 0, 80003, 9);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("…う～ん、今のはちょっと\n違う感じがしますね\n堅苦しかったかもしれません", 0, 0, "", 105801, 21, 210, "ペコリーヌ", 0, 0, 80003, 9);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("あと６日で2.5周年ですか…", 0, 0, "", 105801, 22, 211, "ペコリーヌ", 0, 0, 80003, 9);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("この年月がオイッスーの\n歴史なんだと思うと\nじ～んとしちゃいます！\nやばいですね☆", 0, 0, "", 105801, 23, 212, "ペコリーヌ", 0, 0, 80003, 9);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("生放送で最高のオイッスー☆　を\nみなさんにお届けするために\n頑張らないと！\nそれじゃあもう一度…", 0, 0, "", 105801, 24, 213, "ペコリーヌ", 0, 0, 80003, 9);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("オイッスー☆", 0, 0, "", 105801, 25, 214, "ペコリーヌ", 0, 0, 80003, 9);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("…うう～ん、どうしてでしょう\nまだ何かが違う気がします…\nもしかしたら\nおなかが空きすぎてるとか？", 0, 0, "", 105801, 26, 215, "ペコリーヌ", 0, 0, 80003, 9);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今さっき食べたばっかりですけど\nおなかが減っては\n良いオイッスー☆　は\n出せませんよね！", 0, 0, "", 105801, 27, 216, "ペコリーヌ", 0, 0, 80003, 9);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("そうと決まれば、コッコロちゃんと\nキャルちゃんを誘って\nごはんにしましょう！\n善は急げです！", 0, 0, "", 105801, 28, 217, "ペコリーヌ", 0, 0, 80003, 9);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("あ、二人が丁度いいところに！\nオイッス～☆　…ああ！！\n今の、今のですよ～♪", 0, 0, "", 105801, 29, 218, "ペコリーヌ", 0, 0, 80003, 9);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("なるほど、どんな時も\n自然体が一番ってことですね！\nこの調子で、生放送も\n頑張っちゃいます♪", 0, 0, "", 105801, 30, 219, "ペコリーヌ", 0, 0, 80003, 9);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("2.5周年まで残り５日ですが\nその前にもうすぐ生放送ですよ！\nコッコロちゃん\n準備の方はどうですか？", 0, 0, "", 105801, 31, 220, "ペコリーヌ", 0, 0, 80003, 10);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("はい。わたくし、しっかりと\n備えてまいりました\n万事抜かりはございません", 1, 0, "", 105901, 29, 221, "コッコロ", 0, 0, 80003, 10);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("おお～すごい自信を感じます…！\nいい生放送になりそうですね☆\n……あれ？　なんだかこの辺り\n揺れていませんか？", 0, 0, "", 105801, 32, 222, "ペコリーヌ", 0, 0, 80003, 10);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("…………", 2, 0, "", 106001, 39, 223, "キャル", 0, 0, 80003, 10);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("キャルさま？\nお風邪をひかれたんでしょうか\nひどい震えですが…", 1, 0, "", 105901, 30, 224, "コッコロ", 0, 0, 80003, 10);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("かかかか風邪じゃないわよ！\nここここれはただ\nななな生放送が楽しみ過ぎて\nワワワワクワクが止まらないだけ！", 2, 0, "", 106001, 40, 225, "キャル", 0, 0, 80003, 10);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("大丈夫ですかキャルちゃん！？\nそうだ、これを飲んでください！", 0, 0, "", 105801, 33, 226, "ペコリーヌ", 0, 0, 80003, 10);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("きき気がきくじゃない、ありがとっ\nごくっ、んく…ぶはぁっ！？\nちょっと何飲ませたの！？\n辛っ！　苦ぁ！？　甘ぁっ！？", 2, 0, "", 106001, 41, 227, "キャル", 0, 0, 80003, 10);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("これは魔物のエキスに薬草に\nその他色んなものを混ぜた\n特製の栄養ドリンクです！", 0, 0, "", 105801, 34, 228, "ペコリーヌ", 0, 0, 80003, 10);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("これを飲めば体ぽかぽかで\n元気いっぱいですよ♪", 0, 0, "", 105801, 35, 229, "ペコリーヌ", 0, 0, 80003, 10);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("このアホリーヌ！\n風邪じゃないって言ったでしょ！？\nどさくさに紛れて\nそんな恐ろしいもん飲ませんな～！", 2, 0, "", 106001, 42, 230, "キャル", 0, 0, 80003, 10);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("キャルさま\n震えが収まっておりますね\nよかったです…\nわたくし、心配いたしました", 1, 0, "", 105901, 31, 231, "コッコロ", 0, 0, 80003, 10);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("え？　ああ、ホントね…って\nだから風邪じゃないって\n言ってるのに…\nまあいいわこの際なんでも", 2, 0, "", 106001, 43, 232, "キャル", 0, 0, 80003, 10);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("えっへへ～♪　いつも通りの\nキャルちゃんに戻りましたし\n素敵な生放送が出来そうですね！\n今から楽しみです☆", 0, 0, "", 105801, 36, 233, "ペコリーヌ", 0, 0, 80003, 10);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ランドソルのみなさま、こんにちは\n生放送の会場設営を担当しています\n【ギルド管理協会】のカリンです", 0, 0, "", 190801, 6, 234, "カリン", 0, 0, 80003, 11);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("【美食殿】のみなさんは\nまもなく始まる生放送に向けて\n最後の調整のため\n席を外しています", 0, 0, "", 190801, 7, 235, "カリン", 0, 0, 80003, 11);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("頑張っている３人の\n邪魔をするわけには\nいきませんので、ご容赦ください", 0, 0, "", 190801, 8, 236, "カリン", 0, 0, 80003, 11);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ですので、本日は私から\n【美食殿】のみなさんの様子を\nお伝えさせていただこうと思います", 0, 0, "", 190801, 9, 237, "カリン", 0, 0, 80003, 11);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("まずはペコリーヌさんですが…\n何やら大量のおにぎりを\n食べているようです\nえっと…栄養は大事ですよね", 0, 0, "", 190801, 10, 238, "カリン", 0, 0, 80003, 11);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("次にコッコロさんですが\nこちらは発声練習をしています", 0, 0, "", 190801, 11, 239, "カリン", 0, 0, 80003, 11);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("一生懸命、小さなお口を開けて\n声を出す姿が応援したくなりますね", 0, 0, "", 190801, 12, 240, "カリン", 0, 0, 80003, 11);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("そしてキャルさんは…\nこれは…堂々としたものですね\n何もせず、ただ立ち尽くして…", 0, 0, "", 190801, 13, 241, "カリン", 0, 0, 80003, 11);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("あれ？\nもしかして緊張で気を失って…？", 0, 0, "", 190801, 14, 242, "カリン", 0, 0, 80003, 11);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("…ええと\n【美食殿】のみなさんは\nやる気十分なようですね！", 0, 0, "", 190801, 15, 243, "カリン", 0, 0, 80003, 11);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("３人とも生放送を\nいいものにしようと\n全力で頑張ってくれていますので\nどうかご期待ください", 0, 0, "", 190801, 16, 244, "カリン", 0, 0, 80003, 11);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("それでは\nまた明日お会いしましょう♪", 0, 0, "", 190801, 17, 245, "カリン", 0, 0, 80003, 11);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("2.5周年まであと３日！\nそして生放送は明日！\nなんかいよいよって感じね…", 0, 0, "", 106001, 44, 246, "キャル", 0, 0, 80003, 12);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("３人でい～っぱい練習しましたし\nきっと大丈夫ですよ☆", 2, 0, "", 105801, 37, 247, "ペコリーヌ", 0, 0, 80003, 12);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ペコリーヌさまに\n大丈夫と言ってもらえると\nとても心強いですね", 1, 0, "", 105901, 32, 248, "コッコロ", 0, 0, 80003, 12);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("信じすぎちゃだめよコロ助\nこいつはなーんにも\n考えてないだけなんだから", 0, 0, "", 106001, 45, 249, "キャル", 0, 0, 80003, 12);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ひどいですよぉキャルちゃ～ん！", 2, 0, "", 105801, 38, 250, "ペコリーヌ", 0, 0, 80003, 12);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ふふ。お二人とも\n普段通りの様子で\n安心いたしました", 1, 0, "", 105901, 33, 251, "コッコロ", 0, 0, 80003, 12);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("はいっ☆\n生放送でもなんでも\n全力全開、わたしらしく\nぶつかっていくだけです！", 2, 0, "", 105801, 39, 252, "ペコリーヌ", 0, 0, 80003, 12);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("そうね。おめでたいことなんだし\nここまで来たんなら\n楽しめるだけ\n楽しむしかないわよね！", 0, 0, "", 106001, 46, 253, "キャル", 0, 0, 80003, 12);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("わたくしも、普段よりも心が\n熱くなっております\nこの胸の気持ちをお伝えできるよう\n精一杯努力いたします…！", 1, 0, "", 105901, 34, 254, "コッコロ", 0, 0, 80003, 12);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("それでは、いきましょう！\n明日の生放送、絶対に\n成功させましょうね☆", 2, 0, "", 105801, 40, 255, "ペコリーヌ", 0, 0, 80003, 12);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("えっと、最初のひと言は…あれ？\nキャルちゃん、わたし\n何て言うんでしたっけ？", 0, 0, "", 105801, 41, 256, "ペコリーヌ", 0, 0, 80003, 13);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("は！？\nなにいきなりど忘れしてるの！？\nっていうかあんた、台本は！？", 2, 0, "", 106001, 47, 257, "キャル", 0, 0, 80003, 13);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("忘れてきちゃいました☆", 0, 0, "", 105801, 42, 258, "ペコリーヌ", 0, 0, 80003, 13);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("忘れてきちゃいました☆\nで済ませられると思ってんの！？\nほら、あたし二冊持ってきたから\nこれ使いなさい！", 2, 0, "", 106001, 48, 259, "キャル", 0, 0, 80003, 13);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("マイクとは、こんな高い位置に\nあるものなのですね…！\n背伸びをすれば、何とか…\nう～ん、うぅ～ん…！", 1, 0, "", 105901, 35, 260, "コッコロ", 0, 0, 80003, 13);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("あぁもう\n少し下げればいいでしょ！？\nこれくらいでいい？\nまったく、世話が焼けるわね…", 2, 0, "", 106001, 49, 261, "キャル", 0, 0, 80003, 13);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("あれ？\nキャルちゃん、後ろ髪が\nはねちゃってますよ？", 0, 0, "", 105801, 43, 262, "ペコリーヌ", 0, 0, 80003, 13);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("え？　うそっ！？\nちゃんと確かめてきたのに！\nどこどこ！？", 2, 0, "", 106001, 50, 263, "キャル", 0, 0, 80003, 13);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("キャルさま、動かないで\nくださいまし。今くしで…\nはい、直りましたよ", 1, 0, "", 105901, 36, 264, "コッコロ", 0, 0, 80003, 13);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("あ、ありがと…はぁ。生放送\n本番までもうすぐなのに\nこんなことしてる場合じゃ\nないわよね", 2, 0, "", 106001, 51, 265, "キャル", 0, 0, 80003, 13);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("はい、時間は残りわずかです\nですが、慌ただしく\n動き回るこの時間も\nなんだか楽しくて…♪", 1, 0, "", 105901, 37, 266, "コッコロ", 0, 0, 80003, 13);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("コロ助、あんた…って\nそうじゃなくて！\n胸にジンワリきてる\n暇なんかないでしょ…！？", 2, 0, "", 106001, 52, 267, "キャル", 0, 0, 80003, 13);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("あはは♪\nキャルちゃんの動きが\nとっても面白いです♪\nやばいですね☆", 0, 0, "", 105801, 44, 268, "ペコリーヌ", 0, 0, 80003, 13);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ふふ\nきっと面白い生放送になると\nわたくし、確信しております", 1, 0, "", 105901, 38, 269, "コッコロ", 0, 0, 80003, 13);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("絶対絶対、間違いありません！\n見てくれるみなさんが\n笑顔になれる時間を\nお届けしましょう！", 0, 0, "", 105801, 45, 270, "ペコリーヌ", 0, 0, 80003, 13);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("そんなの当然でしょ！\n誰が見たって面白いって\n言ってもらえるように\nあれだけ準備したんだから！", 2, 0, "", 106001, 53, 271, "キャル", 0, 0, 80003, 13);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("それでは\n記念日直前生放送！\n楽しみにしててくださいね☆", 0, 0, "", 105801, 46, 272, "ペコリーヌ", 0, 0, 80003, 13);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("こんにちは\n【ギルド管理協会】のカリンです", 0, 0, "", 190801, 18, 273, "カリン", 0, 0, 80003, 14);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("昨日の生放送は\nいかがだったでしょうか？", 0, 0, "", 190801, 19, 274, "カリン", 0, 0, 80003, 14);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("たくさんの笑顔と喜びと\nそして驚きを受け取って\nいただけたのではないかと思います", 0, 0, "", 190801, 20, 275, "カリン", 0, 0, 80003, 14);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("そしていよいよ\n明日は2.5周年の当日\n待ちに待った記念日を\n迎えることとなります", 0, 0, "", 190801, 21, 276, "カリン", 0, 0, 80003, 14);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("【美食殿】のみなさんも\n張り切って様々な準備を\nされていますよ", 0, 0, "", 190801, 22, 277, "カリン", 0, 0, 80003, 14);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("【ギルド管理協会】も\n万全のサポート体制で\n協力してまいりたいと思います", 0, 0, "", 190801, 23, 278, "カリン", 0, 0, 80003, 14);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("…ふふ、本当に楽しみですね\n【ギルド管理協会】の職員として\nだけではなく、私個人としても…", 0, 0, "", 190801, 24, 279, "カリン", 0, 0, 80003, 14);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("この記念日を迎えられることが\n心から楽しみですし\n幸せを感じています", 0, 0, "", 190801, 25, 280, "カリン", 0, 0, 80003, 14);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("きっと【美食殿】のみなさんは\nそれ以上に心を弾ませて\nいることでしょう", 0, 0, "", 190801, 26, 281, "カリン", 0, 0, 80003, 14);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("それでは\n明日からの2.5周年を\nどうぞ、お楽しみに…♪", 0, 0, "", 190801, 27, 282, "カリン", 0, 0, 80003, 14);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("準備はいいですかっ？\n…いっきますよー！", 0, 0, "", 105801, 47, 283, "ペコリーヌ", 0, 0, 80003, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("祝！", 2, 0, "", 106001, 54, 284, "キャル", 0, 0, 80003, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("2.5周年！", 1, 0, "", 105901, 39, 285, "コッコロ", 0, 0, 80003, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("おめでとうございま～す☆", 0, 0, "", 105801, 48, 286, "ペコリーヌ", 0, 0, 80003, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("少し前まではまだまだ先じゃない\nとか言ってたけど\n本当にあっという間だったわね", 2, 0, "", 106001, 55, 287, "キャル", 0, 0, 80003, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("光陰矢の如し…\nとはこのことでございますね\nでも、今日という日を無事に\n迎えることができて良かったです", 1, 0, "", 105901, 40, 288, "コッコロ", 0, 0, 80003, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("コッコロちゃん！　キャルちゃん！\n落ち着くには\nまだ早いですよ！\n盛り上がるのはこれからです☆", 0, 0, "", 105801, 49, 289, "ペコリーヌ", 0, 0, 80003, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ほんとあんたはいつも\n全力全開ねー\nでもそうね、記念日なんだし\nパーっといきましょ！", 2, 0, "", 106001, 56, 290, "キャル", 0, 0, 80003, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ええ、わたくしも全力全開で\nまいります…！\n主さま、さあ\nどうぞ手を取ってくださいまし…♪", 1, 0, "", 105901, 41, 291, "コッコロ", 0, 0, 80003, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("あんたもコロ助も、浮かれて\n転ぶんじゃないわよ？\n…仕方ないから、あたしも\n手を繋いであげるわよ", 2, 0, "", 106001, 57, 292, "キャル", 0, 0, 80003, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("あー！　二人ともずるいです！\nわたしもっ、ギュー♪", 0, 0, "", 105801, 50, 293, "ペコリーヌ", 0, 0, 80003, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ちょっ、ペコリーヌ！\nくっつき過ぎよ！", 2, 0, "", 106001, 58, 294, "キャル", 0, 0, 80003, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("記念日だから\n平気平気♪\nやばいですね☆", 0, 0, "", 105801, 51, 295, "ペコリーヌ", 0, 0, 80003, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("意味分かんないわよ！", 2, 0, "", 106001, 59, 296, "キャル", 0, 0, 80003, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ふふ。このめでたき日に\n喜びがあふれておりますね\n主さまは…いかがでしょうか？", 1, 0, "", 105901, 42, 297, "コッコロ", 0, 0, 80003, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("喜んでいただけているならば\nわたくしはとてもとても\n幸せでございます", 1, 0, "", 105901, 43, 298, "コッコロ", 0, 0, 80003, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("さぁ、2.5周年を\n楽しみ尽くしますよ☆\nまだまだ食べたいものもありますし\nやりたいこともたくさんです！", 0, 0, "", 105801, 52, 299, "ペコリーヌ", 0, 0, 80003, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("分かった、分かったから\n引っ張るんじゃないわよ！\n…そんな掴まなくても\nちゃんとついていくから", 2, 0, "", 106001, 60, 300, "キャル", 0, 0, 80003, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ペコリーヌさま…キャルさま…\n主さま…共にまいりましょう\nどこまでも…！", 1, 0, "", 105901, 44, 301, "コッコロ", 0, 0, 80003, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("はい！　それでは2.5周年\n食べつくしツアーへ！\nそして、その先の未来へ\n向かって出発しましょう！", 0, 0, "", 105801, 53, 302, "ペコリーヌ", 0, 0, 80003, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("2.5周年\nありがとうございます！", 0, 1, "105901,45,106001,61", 105801, 54, 303, "ペコリーヌ・コッコロ・キャル", 0, 0, 80003, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("新年を迎え、新たに始まる一日を\nおみくじで占ってみませんか？\n良い運勢であるほど、\n沢山のプレゼントが貰えますよ♪", 1, 0, "", 190804, 1, 304, "カリン", 1, 0, 60002, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は姫吉！　どんな不可能も可能にできちゃう！　　　　仲間と食卓を囲めばさらに運気上昇よ！　ただし魔物料理以外！", 2, 0, "", 0, 0, 305, "", 1, 1, 60002, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は姫吉！　やること全てが最高潮！　やばいですね☆　ラッキーアイテムはおにぎり！　お腹一杯で幸せが続くでしょう！", 2, 0, "", 0, 0, 306, "", 1, 1, 60002, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は姫吉！　最強の運勢でどんなドジも跳ね除けます！　大切な人と一緒に、最高の一日になること間違いなし！", 2, 0, "", 0, 0, 307, "", 1, 1, 60002, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は姫吉！　どんな挑戦も上手くいく、最高の運勢です！理想の自分に変身できる絶好の機会！　新しい一歩を踏み出そう！", 2, 0, "", 0, 0, 308, "", 1, 1, 60002, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は姫吉！　やること全てが上手くいく最高の一日！　　あなたの活躍に先生もにっこりです。いい子いい子♪", 2, 0, "", 0, 0, 309, "", 2, 1, 60002, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は大吉！　お裁縫好きな女の子のお墨付きです！　　　お世話したがりの妹にめいっぱい愛されちゃうかも！？", 2, 0, "", 0, 0, 310, "", 1, 2, 60002, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は大吉！　ラッキーカラーは赤！　　　　　　　　　　湧き上がるアイデアの数々に、高笑いが止まりませんわ！", 2, 0, "", 0, 0, 311, "", 1, 2, 60002, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は大吉！　ラッキーワードは「ちぇる～ん♪」　　　　出会う人みんなに言ってあげると、ハッピーになれますよ！", 2, 0, "", 0, 0, 312, "", 1, 2, 60002, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は大吉！　運勢はバッチリで無敵状態！　　　　　　　龍眼で全てを見通して、思い通りの一日を過ごしましょう！", 2, 0, "", 0, 0, 313, "", 1, 2, 60002, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は大吉！　悩んでいたことが解決しそうです！　　　　たまには勉強も仕事も忘れて、心あたたまる家族と過ごしましょ！", 2, 0, "", 0, 0, 314, "", 2, 2, 60002, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は中吉！　家の中でゆっくり過ごすのがよさそう！　　ラッキーアイテムはゲームよ！　ベストスコアを更新できるかも？", 2, 0, "", 0, 0, 315, "", 1, 3, 60002, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は中吉！　上手くなりたいことに積極的に挑戦してみてサックス好きの妹が、手取り足取りサポートしてくれるかも～？", 2, 0, "", 0, 0, 316, "", 1, 3, 60002, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は中吉！　仕事運が急上昇中です！　　　　　　　　　きっと「煉獄に舞う一陣の疾風」の如き活躍ができますよ！", 2, 0, "", 0, 0, 317, "", 1, 3, 60002, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は中吉！　日頃の努力が報われます！　　　　　　　　親しい友人がいるなら報告してみて。一緒に喜んでくれるはずだ。", 2, 0, "", 0, 0, 318, "", 1, 3, 60002, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は中吉！　商売運が上がってきています！　　　　　　ラッキーアイテムはたい焼き！　和菓子パワーで売上アップです！", 2, 0, "", 0, 0, 319, "", 1, 3, 60002, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は中吉！　チャンスを待つと良い結果に！　　　　　　ラッキーアイテムのプリンを食べて、運を呼び込みましょう！", 2, 0, "", 0, 0, 320, "", 1, 3, 60002, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は中吉！　運気が着々と上昇中！　　　　　　　　　　精霊の加護を受けたかのごとく、色々な事がうまくいきますよ♪", 2, 0, "", 0, 0, 321, "", 2, 3, 60002, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は小吉！　まだ見ぬ危険が隠れているかも！　　　　　でも安心しろ！　提督が貴公を守ってくれるはずだぞ！", 2, 0, "", 0, 0, 322, "", 1, 4, 60002, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は小吉！　いろんな事件が起こる一日になりそう！　　状況をよく観察してみようじゃないか！　まさに探偵のごとくね！", 2, 0, "", 0, 0, 323, "", 1, 4, 60002, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は小吉！　気の向くままに過ごすのが幸せへの近道！　美味い魚を食べて猫を眺めて、自然体で過ごすのはどうだい？", 2, 0, "", 0, 0, 324, "", 1, 4, 60002, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は小吉！　運気は高いけども、ハプニングには注意！　出かけた先で、「ふしんしゃ」扱いされてしまうかも……", 2, 0, "", 0, 0, 325, "", 1, 4, 60002, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は小吉！　同腹一心の友だちが見つかるかも！　　　　キーワードは「ユニちゃんズ」、記憶に刻みましょう！", 2, 0, "", 0, 0, 326, "", 1, 4, 60002, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は小吉！　周りに流されず、マイペースな一日を！　　ただし寝すぎには注意ぐうたらし過ぎず適度な運動を、だってさ～", 2, 0, "", 0, 0, 327, "", 1, 4, 60002, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は小吉！　根を詰めずにリラックスすると運気向上！　ラッキーパーソンはアイドル。歌があなたを幸せにしてくれます♪", 2, 0, "", 0, 0, 328, "", 2, 4, 60002, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("おみくじの結果はどうでしたか？\n新たに始まる一日が、あなたに\nとって良い日になりますように\nまた明日も遊びに来て下さいね♪", 3, 0, "", 190804, 2, 329, "カリン", 0, 0, 60002, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("おみくじは楽しんで頂けましたか？\nあなたの新たなる年が\n素晴らしいものになるよう、\n心からお祈りいたします", 3, 0, "", 190804, 3, 330, "カリン", 0, 0, 60002, 7);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ささ、シェフィさまはこちらへ…", 4, 0, "", 105901, 1, 331, "コッコロ", 0, 0, 80005, 1);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("コッコロさん、どこへ行くの…？\n…え？", 0, 0, "", 106401, 1, 332, "シェフィ", 0, 0, 80005, 1);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("『おめでとうございます！\nわ～パチパチー！』\n…という感じでどうですかね！？", 3, 0, "", 105801, 1, 333, "ペコリーヌ", 0, 0, 80005, 1);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ではわたくしも\n後ろからクラッカーを鳴らして\n応戦いたします\nああ、当日が待ち遠しいですね", 4, 0, "", 105901, 2, 334, "コッコロ", 0, 0, 80005, 1);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ええと…\n二人とも何をしているの？", 0, 0, "", 106401, 2, 335, "シェフィ", 0, 0, 80005, 1);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("シェフィは初めてだもんね\nあの日が近いからって\n予行練習してんのよ\n気が早いわよね～", 1, 0, "", 106001, 1, 336, "キャル", 0, 0, 80005, 1);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("あの日…？", 0, 0, "", 106401, 3, 337, "シェフィ", 0, 0, 80005, 1);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("その通りです…\nいよいよ記念すべきあの日が\n近づいてきましたよ！", 3, 0, "", 105801, 2, 338, "ペコリーヌ", 0, 0, 80005, 1);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("『プリンセスコネクト！\nRe:Dive』3.5周年！", 3, 0, "", 105801, 3, 339, "ペコリーヌ", 0, 0, 80005, 1);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("やばいですね☆", 2, 0, "", 190801, 1, 340, "カリン", 0, 0, 80005, 1);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("って、なにしれっと\n参加してんのよカリン！", 1, 0, "", 106001, 2, 341, "キャル", 0, 0, 80005, 1);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ふふ、いいじゃないですか\n【ギルド管理協会】として\n私もみなさんと一緒に\nお祝いをさせてください！", 2, 0, "", 190801, 2, 342, "カリン", 0, 0, 80005, 1);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("それに…記念日が近づけば\nとっておきの情報を\nお届けしますから♪", 2, 0, "", 190801, 3, 343, "カリン", 0, 0, 80005, 1);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("というわけで\n今日からシェフィちゃんも一緒に\nカウントダウンしちゃいましょう！\n3.5周年まで…", 3, 0, "", 105801, 4, 344, "ペコリーヌ", 0, 0, 80005, 1);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("えっ！？　ええとええと…！\nあ、あと14日…！", 0, 0, "", 106401, 4, 345, "シェフィ", 0, 0, 80005, 1);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("3.5周年まであと13日\n豪華に、そして盛大に\nお祝いしたいですね☆", 3, 0, "", 105801, 5, 346, "ペコリーヌ", 0, 0, 80005, 2);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("豪華といえば前にとある貴族さまが\n舞踏会を開かれたそうで\n主さまがそのお手伝いを\nしておりました", 1, 0, "", 105901, 3, 347, "コッコロ", 0, 0, 80005, 2);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("そこで美しい所作を学ばれたので\nわたくしも教えていただきました\nしゃなり、しゃなり…\nいかがでしょう？", 1, 0, "", 105901, 4, 348, "コッコロ", 0, 0, 80005, 2);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("すっごく上手ですよ☆\nまるでお姫様みたいです\nせっかくなのでわたしも\nしゃなりしゃなり", 3, 0, "", 105801, 6, 349, "ペコリーヌ", 0, 0, 80005, 2);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("さすがでございます\nペコリーヌさま", 1, 0, "", 105901, 5, 350, "コッコロ", 0, 0, 80005, 2);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("いや、あんたは\nできなきゃダメでしょ\n本物のお姫様なんだし", 0, 0, "", 106001, 3, 351, "キャル", 0, 0, 80005, 2);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("しゃなり、しゃなり…\nふふ、案外できるものね", 2, 0, "", 106401, 5, 352, "シェフィ", 0, 0, 80005, 2);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("わぁ！\nシェフィちゃん\n姿勢がとってもキレイです♪", 3, 0, "", 105801, 7, 353, "ペコリーヌ", 0, 0, 80005, 2);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("さ、次はキャルさまの\n番でございますよ", 1, 0, "", 105901, 6, 354, "コッコロ", 0, 0, 80005, 2);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("あ、あたしはいいわよ！\nそういうの全然分かんないし…", 0, 0, "", 106001, 4, 355, "キャル", 0, 0, 80005, 2);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("大丈夫\nやってみると結構楽しいわよ\nほらほらっ", 2, 0, "", 106401, 6, 356, "シェフィ", 0, 0, 80005, 2);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("そ、そこまで言うなら…\nしゃなにゅわきゃあっ！", 0, 0, "", 106001, 5, 357, "キャル", 0, 0, 80005, 2);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("いたたた…もぉお～！\nなんであたしがこんな目に～！", 0, 0, "", 106001, 6, 358, "キャル", 0, 0, 80005, 2);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("まぁまぁ\n記念日までに練習すれば\nできるようになるかもしれません\nよろしければお教えいたしますよ", 1, 0, "", 105901, 7, 359, "コッコロ", 0, 0, 80005, 2);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("よし！\nあんたたちができて\nあたしだけできないのはしゃくだし\nやってやろうじゃないの！！", 0, 0, "", 106001, 7, 360, "キャル", 0, 0, 80005, 2);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("3.5周年まであと12日\n記念日当日はもちろんですが\nその日を待つ時間というのも\n心躍ります", 1, 0, "", 105901, 8, 361, "コッコロ", 0, 0, 80005, 3);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("分かりますっ！\nどんな特別な料理を食べられるのか\n考えるだけでワクワクしますよね！", 3, 0, "", 105801, 8, 362, "ペコリーヌ", 0, 0, 80005, 3);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("特別な料理といえば、お祭りですね\nそういえば主さまは学生として\n聖学祭に参加されたこと\nがあるとか…", 1, 0, "", 105901, 9, 363, "コッコロ", 0, 0, 80005, 3);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("聖学祭…って、なにかしら？", 2, 0, "", 106401, 7, 364, "シェフィ", 0, 0, 80005, 3);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("聖テレサ女学院の祭典ですよ\n二つのチームが競い合い\n青春を満喫するのが趣旨のようです", 1, 0, "", 105901, 10, 365, "コッコロ", 0, 0, 80005, 3);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("それってカルミナの\nサプライズライブがあった\nお祭りよね？\nちょっと見たかったかも…", 0, 0, "", 106001, 8, 366, "キャル", 0, 0, 80005, 3);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("カルミナの後の\nライブも好評だったらしいじゃない\n確か、なかよし部\nだったっけ…？", 0, 0, "", 106001, 9, 367, "キャル", 0, 0, 80005, 3);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("なかよし部…\n仲が良さそうな名前で\nやばいですね☆", 3, 0, "", 105801, 9, 368, "ペコリーヌ", 0, 0, 80005, 3);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("いや、そのまんますぎでしょ…", 0, 0, "", 106001, 10, 369, "キャル", 0, 0, 80005, 3);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("聖学祭かぁ…なんだか楽しそうね\nそれになかよし部の人たちも\n気になるわ", 2, 0, "", 106401, 8, 370, "シェフィ", 0, 0, 80005, 3);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("それじゃあわたしたちも、\n負けじと仲良くしましょう♪\nほらほらシェフィちゃん、\nぎゅーっ☆　ですよ♪", 3, 0, "", 105801, 10, 371, "ペコリーヌ", 0, 0, 80005, 3);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("えっ？　ええ…\nぎゅーっ…？", 2, 0, "", 106401, 9, 372, "シェフィ", 0, 0, 80005, 3);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("3.5周年まであと11日！？\nお祝いの準備進んでないんだけど…\nああ～昨日に戻りたいわ…", 0, 0, "", 106001, 11, 373, "キャル", 0, 0, 80005, 4);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("そういえばそんな魔道具があるって\n聞いたことがあるわね\n確か、名前はタイムラーベ…", 2, 0, "", 106401, 10, 374, "シェフィ", 0, 0, 80005, 4);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("なにそれヤバいわね\nでも本当にあるんだったら\n準備よりももっとやり直したいこと\nたくさんあるんだけど…", 0, 0, "", 106001, 12, 375, "キャル", 0, 0, 80005, 4);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("もしや正月の件でしょうか…？\nあの時はお金がなくて\n苦労しましたから", 1, 0, "", 105901, 11, 376, "コッコロ", 0, 0, 80005, 4);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("あれはそうね…\nお金を湯水のように使う\nぺコリーヌを止められたら\nあんな苦労をすることもなかったし", 0, 0, "", 106001, 13, 377, "キャル", 0, 0, 80005, 4);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("そんなこともありましたね！\nやり直したいといえば\n『きゃるきゃる～ん♪』\nの方かと思いましたよ！", 3, 0, "", 105801, 11, 378, "ペコリーヌ", 0, 0, 80005, 4);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("バラすんじゃないわよ\nこのアホリーヌ！\nシェフィはそれ\n知らないんだから！", 0, 0, "", 106001, 14, 379, "キャル", 0, 0, 80005, 4);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("こうなったらもう、なんとか\nタイムラーべを探し出して\n今の会話をなかったことに…\nって、どうしたのよシェフィ", 0, 0, "", 106001, 15, 380, "キャル", 0, 0, 80005, 4);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("うん…もし、私だったら…\n私が知らないみんなとの時間を\n見てみたいな、って…", 2, 0, "", 106401, 11, 381, "シェフィ", 0, 0, 80005, 4);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("シェフィちゃん！　タイムなんとか\nなんかなくても大丈夫ですよ！\n一緒の時間はこれから\nどんどん作ればいいんですから！", 3, 0, "", 105801, 12, 382, "ペコリーヌ", 0, 0, 80005, 4);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("はい、今この瞬間も\n未来にはかけがえのない思い出に\nなっていることでしょう", 1, 0, "", 105901, 12, 383, "コッコロ", 0, 0, 80005, 4);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("だからそんな顔しないの\nほら、お祝いの準備、進めるわよ！", 0, 0, "", 106001, 16, 384, "キャル", 0, 0, 80005, 4);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("みんな…そうね\n最高のお祝いにして\n最高の思い出にしましょう！", 2, 0, "", 106401, 12, 385, "シェフィ", 0, 0, 80005, 4);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("3.5周年まで、あと10日！\nもうすぐですよー！\n楽しみすぎて、やばいですね！", 3, 0, "", 105801, 13, 386, "ペコリーヌ", 0, 0, 80005, 5);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("そういえば…たくさんのおもちゃが\n子どもたちを襲うっていう\n騒動もありましたね…\nなんでも勝手に動き出したとか！", 3, 0, "", 105801, 14, 387, "ペコリーヌ", 0, 0, 80005, 5);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("学校や孤児院とかに\nちっちゃなおもちゃが乗り込んで\n暴れたみたいですよ！", 3, 0, "", 105801, 15, 388, "ペコリーヌ", 0, 0, 80005, 5);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("暴れたって言っても\n所詮はおもちゃじゃない\nどうせちっさいんでしょ？", 0, 0, "", 106001, 17, 389, "キャル", 0, 0, 80005, 5);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("だったら魔法で\n全部ぶっ飛ばせばいいじゃない！\n大したことないわよ！", 0, 0, "", 106001, 18, 390, "キャル", 0, 0, 80005, 5);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("キャルってば…\n相手は子どもが\n大事にしてる物なのよ…？", 2, 0, "", 106401, 13, 391, "シェフィ", 0, 0, 80005, 5);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("乱暴な発言は\nめっ、でございますよ？\n子どもの教育に悪影響を\n与えてしまいますから…", 1, 0, "", 105901, 13, 392, "コッコロ", 0, 0, 80005, 5);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("キャルちゃんだって\n意外と猫グッズとか\nたっくさん集めてますよね？\nもしその子たちが暴れたら…？", 3, 0, "", 105801, 16, 393, "ペコリーヌ", 0, 0, 80005, 5);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("う、うっさいわね！\n意外とか言うな！\n…ま、まあ確かに正面切って\n魔法でぶっ飛ばせないかもね…", 0, 0, "", 106001, 19, 394, "キャル", 0, 0, 80005, 5);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("あはは☆\nキャルちゃんのそういうところ\n好きですよ♪", 3, 0, "", 105801, 17, 395, "ペコリーヌ", 0, 0, 80005, 5);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("そんなキャルちゃんに猫グッズを\nプレゼントしちゃいますね！\n一部で流行っていた、たい焼き屋の\nおまけフィギュアですよ♪", 3, 0, "", 105801, 18, 396, "ペコリーヌ", 0, 0, 80005, 5);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("乱暴に扱ったりしないでくださいね\nひとりでに暴れ出しちゃうかも\nしれませんから！", 3, 0, "", 105801, 19, 397, "ペコリーヌ", 0, 0, 80005, 5);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("3.5周年まであと９日\nここでみなさんに\nビックニュースですよ！", 2, 0, "", 190801, 4, 398, "カリン", 0, 0, 80005, 6);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("3.5周年を祝う生放送に\n去年と同様【美食殿】の\nみなさんにご出演いただくことが\n決定しましたー！", 2, 0, "", 190801, 5, 399, "カリン", 0, 0, 80005, 6);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("…えっ！？", 1, 0, "", 106001, 20, 400, "キャル", 0, 0, 80005, 6);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("本当ですか！？\nそれじゃ今から張り切って\n生放送中に食べる魔物料理を\n作らなくちゃですね☆", 3, 0, "", 105801, 20, 401, "ペコリーヌ", 0, 0, 80005, 6);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("いや…がんばるところは\nそこじゃないような…\nというか去年も出演してたのね\nすごいじゃない！", 0, 0, "", 106401, 14, 402, "シェフィ", 0, 0, 80005, 6);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("はい。とても緊張しますが\nやりがいのある大役です\n一緒にがんばりましょうね\nシェフィさま", 4, 0, "", 105901, 14, 403, "コッコロ", 0, 0, 80005, 6);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("わ、私も出るの！？　でも…\n私も【美食殿】の一人だものね\nそれなら今からしっかり準備をして\nコンディションを整えないと…", 0, 0, "", 106401, 15, 404, "シェフィ", 0, 0, 80005, 6);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ふふん♪\n生放送直前のカチコチになった\nシェフィの姿が楽しみだわ！", 1, 0, "", 106001, 21, 405, "キャル", 0, 0, 80005, 6);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("去年のキャルちゃんは\n緊張しすぎてずっと震えて\nかわいかったですもんね！\n今年もあの姿が見たいです！", 3, 0, "", 105801, 21, 406, "ペコリーヌ", 0, 0, 80005, 6);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ぶっ殺すぞ！？", 1, 0, "", 106001, 22, 407, "キャル", 0, 0, 80005, 6);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("というわけで\n『プリンセスコネクト！\nRe:Dive』の魅力を\nお伝えする生放送をお楽しみに♪", 2, 0, "", 190801, 6, 408, "カリン", 0, 0, 80005, 6);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("3.5周年まであと８日\nでございますよ\n楽しみですね、主さま", 1, 0, "", 105901, 15, 409, "コッコロ", 0, 0, 80005, 7);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("そういえばあんた\n夏休みの宿題は\nきちんとやってるの？", 0, 0, "", 106001, 23, 410, "キャル", 0, 0, 80005, 7);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("宿題…学校に通うのも\n楽しいことばかりじゃ\nないのね", 2, 0, "", 106401, 16, 411, "シェフィ", 0, 0, 80005, 7);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("あれ？　そういえば\n少し前にルーセント学院で\n何かあったような…", 3, 0, "", 105801, 22, 412, "ペコリーヌ", 0, 0, 80005, 7);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ああ、始業式の日に\n大捕り物があったって\n話題になってたわね", 0, 0, "", 106001, 24, 413, "キャル", 0, 0, 80005, 7);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("夏休みを終わらせないって\n騒いでたっていう話？\nあれ本当なの？\n都市伝説だと思ってたわ", 2, 0, "", 106401, 17, 414, "シェフィ", 0, 0, 80005, 7);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("その一件ならよく存じ上げて\nおります。ですから主さま\n次の機会にはわたくしと一緒に\nがんばりましょう", 1, 0, "", 105901, 16, 415, "コッコロ", 0, 0, 80005, 7);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("楽しそう…私も一緒にやりたいな\nママ…じゃ、じゃなくて！\nコッコロさん、私もまざっていい？", 2, 0, "", 106401, 18, 416, "シェフィ", 0, 0, 80005, 7);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("もちろんでございます\n仲良くお勉強いたしましょう", 1, 0, "", 105901, 17, 417, "コッコロ", 0, 0, 80005, 7);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("しれっと教育ママが\n生まれてる…？", 0, 0, "", 106001, 25, 418, "キャル", 0, 0, 80005, 7);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("お勉強は大切ですよ！\nキャルちゃんも一緒に\nがんばりましょう！", 3, 0, "", 105801, 23, 419, "ペコリーヌ", 0, 0, 80005, 7);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("え～～～～！？", 0, 0, "", 106001, 26, 420, "キャル", 0, 0, 80005, 7);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("3.5周年まであと７日〜♪\nふふ～ん♪\nふんふふ～ん♪", 0, 0, "", 106001, 27, 421, "キャル", 0, 0, 80005, 8);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("…\nねぇコッコロさん\nキャル、どうしちゃったの？", 2, 0, "", 106401, 19, 422, "シェフィ", 0, 0, 80005, 8);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("とてもご機嫌そうに\n鼻歌を歌ってらっしゃいますね\n耳も尻尾もリズミカルに\n揺れて…ノリノリでございます", 1, 0, "", 105901, 18, 423, "コッコロ", 0, 0, 80005, 8);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("あれはですね！\nカルミナのみなさんの\nサマーライブのチケットが\n手に入ったからなんですよ♪", 3, 0, "", 105801, 24, 424, "ペコリーヌ", 0, 0, 80005, 8);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ええっ！？\nあのライブのチケットって確か\n入手困難だったんじゃ…", 2, 0, "", 106401, 20, 425, "シェフィ", 0, 0, 80005, 8);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ふふふふ～ん♪\nしゃいにんぐふゅ～ちゃ～♪", 0, 0, "", 106001, 28, 426, "キャル", 0, 0, 80005, 8);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("なるほど…\nキャルさまがあのように\nなってしまうのも頷けますね", 1, 0, "", 105901, 19, 427, "コッコロ", 0, 0, 80005, 8);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("…カルミナの\n『Shining Future』\nの中に、シャイニングフューチャー\nって歌詞はなかったはずだけど…", 2, 0, "", 106401, 21, 428, "シェフィ", 0, 0, 80005, 8);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ふんふ…はっ！？\nあっ、あんたたち！\nなに人の鼻歌を\n勝手に聞いてるのよ！？", 0, 0, "", 106001, 29, 429, "キャル", 0, 0, 80005, 8);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("こっ、これは別に\nカルミナの曲じゃなくて…\nあたしのオリジナルソングよ！\n聞いたらお金取るわよっ！？", 0, 0, "", 106001, 30, 430, "キャル", 0, 0, 80005, 8);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("えへへ、キャルちゃん\nカルミナのサマーライブ\n思いっきり楽しみましょうね☆", 3, 0, "", 105801, 25, 431, "ペコリーヌ", 0, 0, 80005, 8);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("も～っ！\n生暖かい目で見るな～～！\nぶっ殺すわよ～～～！", 0, 0, "", 106001, 31, 432, "キャル", 0, 0, 80005, 8);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("3.5周年まであと６日\n３人も言ってたけど\nあっという間だったわね", 0, 0, "", 106401, 22, 433, "シェフィ", 0, 0, 80005, 9);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("…えっ？\n生放送の意気込み！？\n突然なに！？", 0, 0, "", 106401, 23, 434, "シェフィ", 0, 0, 80005, 9);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ええと…\nとにかく失敗しないように\n台本たくさん読んで…\nそれから…", 0, 0, "", 106401, 24, 435, "シェフィ", 0, 0, 80005, 9);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("えっ！？\nトラブルがあったら\nどうするのかって！？\nそ、それは…！", 0, 0, "", 106401, 25, 436, "シェフィ", 0, 0, 80005, 9);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("とにかく落ち着いて\nスタッフさんの指示を聞いて…", 0, 0, "", 106401, 26, 437, "シェフィ", 0, 0, 80005, 9);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("それから、それから…！\nぅ、ぅぅっ…！", 0, 0, "", 106401, 27, 438, "シェフィ", 0, 0, 80005, 9);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("―びえぇぇ～んっ！！！", 0, 0, "", 106401, 28, 439, "シェフィ", 0, 0, 80005, 9);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("どうされましたか、シェフィさま", 1, 0, "", 105901, 20, 440, "コッコロ", 0, 0, 80005, 9);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ううっ…ひっく…\nママッ…！", 0, 0, "", 106401, 29, 441, "シェフィ", 0, 0, 80005, 9);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("よしよし、緊張されてるのですね\nママが傍におりますよ\n主さま、少々お待ちくださいませ", 1, 0, "", 105901, 21, 442, "コッコロ", 0, 0, 80005, 9);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("…ふぅ\nシェフィさま\n生放送への意気込み\nお話しできそうですか？", 1, 0, "", 105901, 22, 443, "コッコロ", 0, 0, 80005, 9);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("…ううっ\n恥ずかしすぎて\nもう生放送出られない…", 0, 0, "", 106401, 30, 444, "シェフィ", 0, 0, 80005, 9);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("主さま\n3.5周年まであと５日\nでございます", 0, 0, "", 105901, 23, 445, "コッコロ", 0, 0, 80005, 10);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ですがその前に\n生放送がありますね", 0, 0, "", 105901, 24, 446, "コッコロ", 0, 0, 80005, 10);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("…生放送に向けた\n意気込みでございますか？", 0, 0, "", 105901, 25, 447, "コッコロ", 0, 0, 80005, 10);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("もちろんわたくしは\n主さまのために\n全身全霊を込めて\n楽しい時間をご提供いたします", 0, 0, "", 105901, 26, 448, "コッコロ", 0, 0, 80005, 10);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("…と、意気込んでみましたが\nうまくできるか少し不安です\n声が小さくなったり\n間違えてしまったらどうしようと…", 0, 0, "", 105901, 27, 449, "コッコロ", 0, 0, 80005, 10);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ですがわたくしは\n一人ではありません\n【美食殿】のみなさまが\nおります", 0, 0, "", 105901, 28, 450, "コッコロ", 0, 0, 80005, 10);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("どんな困難も\nみなさまと一緒なら\n乗り越えられると\nわたくし、確信しております", 0, 0, "", 105901, 29, 451, "コッコロ", 0, 0, 80005, 10);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("それに今回はシェフィさまも\nご参加されるわけですし\nママとしてお手本に\nならねばなりませんね", 0, 0, "", 105901, 30, 452, "コッコロ", 0, 0, 80005, 10);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("主さま。3.5周年も\n食卓を囲んでいる時のような\n楽しい思い出を\n一緒に作りましょうね", 0, 0, "", 105901, 31, 453, "コッコロ", 0, 0, 80005, 10);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("3.5周年まであと４日！\nやばいですね☆", 0, 0, "", 105801, 26, 454, "ペコリーヌ", 0, 0, 80005, 11);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("はいはい、やばいわね\nというかもうすぐ生放送だけど\nあんた準備はできてるの？", 1, 0, "", 106001, 32, 455, "キャル", 0, 0, 80005, 11);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ばっちりオイッスー☆　ですよ！\n『王家の装備』も全開です！", 0, 0, "", 105801, 27, 456, "ペコリーヌ", 0, 0, 80005, 11);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("あとは前回を超える\n最高のオイッスー☆　を\nお届けできるように\n練習あるのみですかね！", 0, 0, "", 105801, 28, 457, "ペコリーヌ", 0, 0, 80005, 11);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("キャルちゃんは\nどうなんですか？\nオイッスー☆　を\n毎日ちゃんと練習してますか？", 0, 0, "", 105801, 29, 458, "ペコリーヌ", 0, 0, 80005, 11);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("はぁ！？　なんであたしまで\nその変なあいさつを練習しないと\nいけないのよ！", 1, 0, "", 106001, 33, 459, "キャル", 0, 0, 80005, 11);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("もしかしてやってないんですか？\nダメですよキャルちゃん！\nシェフィちゃんだってちゃんと\n毎日練習してるのに！", 0, 0, "", 105801, 30, 460, "ペコリーヌ", 0, 0, 80005, 11);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("こうなったらわたしがキャルちゃん\nにオイッスー☆　の『オ』から\nしっかり教えてあげないと！", 0, 0, "", 105801, 31, 461, "ペコリーヌ", 0, 0, 80005, 11);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("オイッスー☆　の『オ』は\n口を大きく開いて〜\nドラゴンの骨つき肉に\nかぶりつく直前をイメージして〜", 0, 0, "", 105801, 32, 462, "ペコリーヌ", 0, 0, 80005, 11);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("だからあたしはやるなんて一言も…", 1, 0, "", 106001, 34, 463, "キャル", 0, 0, 80005, 11);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("オイッスー☆", 0, 0, "", 105801, 33, 464, "ペコリーヌ", 0, 0, 80005, 11);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("聞きなさいっての！！", 1, 0, "", 106001, 35, 465, "キャル", 0, 0, 80005, 11);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("3.5周年まであと３日…\nそして生放送は、明日…", 2, 0, "", 106401, 31, 466, "シェフィ", 0, 0, 80005, 12);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("もっと台本を\n読み込んでおかないと…\nあと発声練習も…", 2, 0, "", 106401, 32, 467, "シェフィ", 0, 0, 80005, 12);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("おいっす！\n…こうじゃなかったわね\nええと確か…", 2, 0, "", 106401, 33, 468, "シェフィ", 0, 0, 80005, 12);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("うう…あんなに練習したのに\nこれじゃみんなに迷惑かけちゃう…", 2, 0, "", 106401, 34, 469, "シェフィ", 0, 0, 80005, 12);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("【美食殿】の一員として\n認められるように\n頑張らないといけないのに\nよし、もう一度…", 2, 0, "", 106401, 35, 470, "シェフィ", 0, 0, 80005, 12);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("やってますねシェフィちゃん！", 3, 0, "", 105801, 34, 471, "ペコリーヌ", 0, 0, 80005, 12);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("なによ、考えることは\nみんな同じってこと？", 0, 0, "", 106001, 36, 472, "キャル", 0, 0, 80005, 12);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ふふ。シェフィさま\nよろしければ\n仲間に入れてください\n一緒にやればきっとうまくできます", 1, 0, "", 105901, 32, 473, "コッコロ", 0, 0, 80005, 12);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("みんな…もちろんよ！", 2, 0, "", 106401, 36, 474, "シェフィ", 0, 0, 80005, 12);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("それじゃ明日の生放送に向けて\n一緒に練習がんばりましょう☆", 3, 0, "", 105801, 35, 475, "ペコリーヌ", 0, 0, 80005, 12);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("3.5周年まであと２日と\n迫った本日は…\nいよいよ生放送です！", 2, 0, "", 190801, 7, 476, "カリン", 0, 0, 80005, 13);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("【美食殿】のみなさんが\n準備に入られていますので\nそれぞれ繋いでみましょう！\nまずはペコリーヌさんです！", 2, 0, "", 190801, 8, 477, "カリン", 0, 0, 80005, 13);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日もオイッスー☆\nみんなで一緒に\nオイッスー☆", 3, 0, "", 105801, 36, 478, "ペコリーヌ", 0, 0, 80005, 13);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("お手本になるような\n発声練習ですね！\nそれでは続いてコッコロさん", 2, 0, "", 190801, 9, 479, "カリン", 0, 0, 80005, 13);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("はじめちょろちょろ\nなかぱっぱ～♪\n生放送前にみなさまで\n食卓を囲んで英気を養いましょう", 4, 0, "", 105901, 33, 480, "コッコロ", 0, 0, 80005, 13);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("さすが【美食殿】のママですね！\nそしてキャルさんは…", 2, 0, "", 190801, 10, 481, "カリン", 0, 0, 80005, 13);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("大丈夫…大丈夫…\nあたしは大丈夫…", 1, 0, "", 106001, 37, 482, "キャル", 0, 0, 80005, 13);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("す、すごく震えてますけど\n大丈夫でしょうか…？\nそして今回初参加となる\n期待の新人シェフィさん！", 2, 0, "", 190801, 11, 483, "カリン", 0, 0, 80005, 13);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("あうー？", 0, 0, "", 106401, 37, 484, "シェフィ", 0, 0, 80005, 13);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("あ…", 4, 1, "105901,34,106001,38,190801,12", 105801, 37, 485, "みんな", 0, 0, 80005, 13);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ちょ、ちょっとシェフィ！？\nなに赤ちゃん返りしてん―\nあ痛ぁっ！\n噛んだわこいつーっ！", 1, 0, "", 106001, 39, 486, "キャル", 0, 0, 80005, 13);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("シェフィさま\n緊張しすぎて\nしまったのでしょうね…\nおーよしよし…", 4, 0, "", 105901, 35, 487, "コッコロ", 0, 0, 80005, 13);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("シェフィちゃん！\nそういう時は手のひらに\n好きな文字を書いて\n食べちゃうといいですよ！", 3, 0, "", 105801, 38, 488, "ペコリーヌ", 0, 0, 80005, 13);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("…ええと、現場からは以上です！\n生放送はもうすぐ！\n特別なお知らせもありますので\nどうぞお楽しみに！", 2, 0, "", 190801, 13, 489, "カリン", 0, 0, 80005, 13);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("3.5周年の記念日も\nいよいよ明日ね\n…って、あれ？", 2, 0, "", 106401, 38, 490, "シェフィ", 0, 0, 80005, 14);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("記念日はこの森へ行きませんか！？\nすっごく美味しいお肉が\nとれるんです☆", 3, 0, "", 105801, 39, 491, "ペコリーヌ", 0, 0, 80005, 14);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("うげ、またあの魔物？\nさすがに今度は\n丸焼きとかはやめてよね…\n見た目がヤバすぎるし", 0, 0, "", 106001, 40, 492, "キャル", 0, 0, 80005, 14);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ふふ、キャルさまもだいぶ\n魔物肉に慣れてきたようですね\n調理ならばわたくしに\nお任せください♪", 1, 0, "", 105901, 36, 493, "コッコロ", 0, 0, 80005, 14);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("みんな、何をしているの？\nなんだか、\n不穏な単語が聞こえたんだけど…", 2, 0, "", 106401, 39, 494, "シェフィ", 0, 0, 80005, 14);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("シェフィちゃん！\n明日の食べ尽くしツアーの\n相談をしてたんですよ！", 3, 0, "", 105801, 40, 495, "ペコリーヌ", 0, 0, 80005, 14);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("はい。明日は【美食殿】の\n一員となったシェフィさまと一緒に\n初めて記念日を過ごすのですから\n特別なコース料理を用意しませんと", 1, 0, "", 105901, 37, 496, "コッコロ", 0, 0, 80005, 14);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ふふん♪\n猫の毛も逆立つような\nあれこれを食べさせられるから\n覚悟しておいたほうがいいわよ？", 0, 0, "", 106001, 41, 497, "キャル", 0, 0, 80005, 14);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("へ、へぇ…", 2, 0, "", 106401, 40, 498, "シェフィ", 0, 0, 80005, 14);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("期待しててくださいね！\nシェフィちゃんとあなたに\n『おいちー！』って喜んでもらえる\n最高のごちそうを準備しますから☆", 3, 0, "", 105801, 41, 499, "ペコリーヌ", 0, 0, 80005, 14);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ええと…その…うーんと…\nわ、分かったわ\n私も【美食殿】の一員だもの", 2, 0, "", 106401, 41, 500, "シェフィ", 0, 0, 80005, 14);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("それにあなたも一緒みたいだし\n最後までがんばってみるわ…！", 2, 0, "", 106401, 42, 501, "シェフィ", 0, 0, 80005, 14);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("それではいつものあれを\nやりましょう！\n準備はいいですかっ？\n…いっきますよー！", 3, 0, "", 105801, 42, 502, "ペコリーヌ", 0, 0, 80005, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("祝！", 1, 0, "", 106001, 42, 503, "キャル", 0, 0, 80005, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("3.5周年！", 4, 0, "", 105901, 38, 504, "コッコロ", 0, 0, 80005, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("おめでとうございます！", 0, 0, "", 106401, 43, 505, "シェフィ", 0, 0, 80005, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("この日を迎えられたのも\nあなたが『プリンセスコネクト！\nRe:Dive』を遊んでくれている\nおかげです！", 2, 0, "", 190801, 14, 506, "カリン", 0, 0, 80005, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ということで\nみなさんからあなたへ一言ずつ\n感謝の言葉をどうぞ！", 2, 0, "", 190801, 15, 507, "カリン", 0, 0, 80005, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("感謝の言葉ですか？　わたしは\n毎日あなたに感謝してますよ\n【美食殿】の仲間になってくれて…\n一緒にごはんを食べてくれて…", 3, 0, "", 105801, 43, 508, "ペコリーヌ", 0, 0, 80005, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("なにより今でもわたしをぺコリーヌ\nって呼んでくれてありがとうござい\nます。これからもわたしはあなたの\nぺコリーヌです！　やばいですね☆", 3, 0, "", 105801, 44, 509, "ペコリーヌ", 0, 0, 80005, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("えっ！？　今度はあたし！？\n感謝って…まぁ、そうね…\nあんたにはあたしが\n辛くて苦しい時に助けてもらって…", 1, 0, "", 106001, 43, 510, "キャル", 0, 0, 80005, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("でもおかげで色々吹っ切れたわ！\nもしあんたが困ってたら今度は\nあたしが助けてあげるから\nその時はちゃんと言いなさいよ！", 1, 0, "", 106001, 44, 511, "キャル", 0, 0, 80005, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ええと…次は私ね\n実はよく覚えてないのだけど\n空から落ちてきた私を受け止めて\nくれたのはあなたなのでしょう？", 0, 0, "", 106401, 44, 512, "シェフィ", 0, 0, 80005, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("最初に私を見つけてくれたのが\nあなたで良かったって思ってるの\nおかげで私は居場所を見つけたから\nあなたがくれたもの、大切にするわ", 0, 0, "", 106401, 45, 513, "シェフィ", 0, 0, 80005, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("では最後にわたくしから…\nわたくしは主さまの元を離れた日…\nこのように記念日をお祝いする\nことは二度とないと思っていました", 4, 0, "", 105901, 39, 514, "コッコロ", 0, 0, 80005, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("ですが、主さまはわたくしを\n迎えにきてくださり、今もこうして\nおそばにおいてくださっています\nわたくしにとって毎日が記念日です", 4, 0, "", 105901, 40, 515, "コッコロ", 0, 0, 80005, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("わたくしたちの物語は\nまだ続いていきます\nこれからも一緒にページを\n作っていきましょうね", 4, 0, "", 105901, 41, 516, "コッコロ", 0, 0, 80005, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("それじゃ\nいつものあれでしめますよ！\nみんなで一緒に、さんはい☆", 3, 0, "", 105801, 45, 517, "ペコリーヌ", 0, 0, 80005, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("これからも\nよろしくおねがいします！", 4, 1, "105901,42,106001,45,106401,46,190801,16", 105801, 46, 518, "みんな", 0, 0, 80005, 15);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("新年を迎え、新たに始まる一日を\nおみくじで占ってみませんか？\n良い運勢であるほど、\n沢山のプレゼントが貰えますよ♪", 1, 0, "", 190804, 1, 519, "カリン", 1, 0, 60003, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は姫吉！　どんな不可能も可能にできちゃう！　　　　仲間と食卓を囲めばさらに運気上昇よ！　ただし魔物料理以外！", 2, 0, "", 0, 0, 520, "", 1, 1, 60003, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は姫吉！　やること全てが最高潮！　やばいですね☆　ラッキーアイテムはおにぎり！　お腹一杯で幸せが続くでしょう！", 2, 0, "", 0, 0, 521, "", 1, 1, 60003, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は姫吉！　羽が生えたように飛躍できる絶好調の運気！新しいことに挑戦するなら今しかないわ！　やってみましょう！", 2, 0, "", 0, 0, 522, "", 1, 1, 60003, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は姫吉！　精霊も新年の幸福をお祝いしています！　　主さまの笑顔が見られて、わたくしも幸せいっぱいでございます♪", 2, 0, "", 0, 0, 523, "", 1, 1, 60003, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は姫吉！　やること全てが上手くいく最高の一日！　　あなたの活躍に先生もにっこりです。いい子いい子♪", 2, 0, "", 0, 0, 524, "", 2, 1, 60003, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は大吉！　お裁縫好きな女の子のお墨付きです！　　　お世話したがりの妹にめいっぱい愛されちゃうかも！？", 2, 0, "", 0, 0, 525, "", 1, 2, 60003, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は大吉！　ラッキーカラーは赤！　　　　　　　　　　湧き上がるアイデアの数々に、高笑いが止まりませんわ！", 2, 0, "", 0, 0, 526, "", 1, 2, 60003, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は大吉！　ラッキーカラーは鮮やかな黄色！　　　　　さらにシマシマのアイテムを持つと、運気倍増らしいッスよ♪", 2, 0, "", 0, 0, 527, "", 1, 2, 60003, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は大吉！　秘められた力が開花するでしょう！　　　　じゃあ、私の龍眼と力比べしてみようか？　ふふ、冗談だよ～", 2, 0, "", 0, 0, 528, "", 1, 2, 60003, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は大吉！　悩んでいたことが解決しそうです！　　　　たまには勉強も仕事も忘れて、心あたたまる家族と過ごしましょ！", 2, 0, "", 0, 0, 529, "", 2, 2, 60003, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は中吉！　家の中でゆっくり過ごすのがよさそう！　　ラッキーアイテムはゲームよ！　ベストスコアを更新できるかも？", 2, 0, "", 0, 0, 530, "", 1, 3, 60003, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は中吉！　上手くなりたいことに積極的に挑戦してみてサックス好きの妹が、手取り足取りサポートしてくれるかも～？", 2, 0, "", 0, 0, 531, "", 1, 3, 60003, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は中吉！　仕事運が急上昇中です！　　　　　　　　　きっと「煉獄に舞う一陣の疾風」の如き活躍ができますよ！", 2, 0, "", 0, 0, 532, "", 1, 3, 60003, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は中吉！　日頃の努力が報われます！　　　　　　　　親しい友人がいるなら報告してみて。一緒に喜んでくれるはずだ。", 2, 0, "", 0, 0, 533, "", 1, 3, 60003, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は中吉！　ラッキーアイテムはかわいいもの！　　　　ア、アタシはかわいいじゃなくてキレイだってば！　も～っ！", 2, 0, "", 0, 0, 534, "", 1, 3, 60003, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は中吉！　チャンスを待つと良い結果に！　　　　　　ラッキーアイテムのプリンを食べて、運を呼び込みましょう！", 2, 0, "", 0, 0, 535, "", 1, 3, 60003, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は中吉！　悩まず行動すれば強運に恵まれる！　　　　守るよりも攻めるが吉だ！　勝負事をするにはいい運勢だな！", 2, 0, "", 0, 0, 536, "", 2, 3, 60003, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は小吉！　まだ見ぬ危険が隠れているかも！　　　　　でも安心しろ！　提督が貴公を守ってくれるはずだぞ！", 2, 0, "", 0, 0, 537, "", 1, 4, 60003, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は小吉！　いろんな事件が起こる一日になりそう！　　状況をよく観察してみようじゃないか！　まさに探偵のごとくね！", 2, 0, "", 0, 0, 538, "", 1, 4, 60003, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は小吉！　気の向くままに過ごすのが幸せへの近道！　美味い魚を食べて猫を眺めて、自然体で過ごすのはどうだい？", 2, 0, "", 0, 0, 539, "", 1, 4, 60003, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES ("今日の運勢は小吉！　難しい頼み事をされるかもしれません！　　うまくやれればきっと成長につながります、挑戦してみましょう！", 2, 0, "", 0, 0, 540, "", 1, 4, 60003, 0);
